class ManagementSwipeRow extends StatefulWidget {
  const ManagementSwipeRow({
    required this.child,
    required this.actions,
    super.key,
  });

  final Widget child;
  final List<ManagementSwipeAction> actions;

  @override
  State<ManagementSwipeRow> createState() => _ManagementSwipeRowState();
}

class _ManagementSwipeRowState extends State<ManagementSwipeRow> {
  static const _actionWidth = 72.0;
  var _offset = 0.0;
  var _isDragging = false;

  double get _actionsWidth => widget.actions.length * _actionWidth;

  void _close() => setState(() {
    _isDragging = false;
    _offset = 0;
  });

  @override
  Widget build(BuildContext context) {
    return ClipRect(
      child: Stack(
        children: [
          if (_offset < 0)
            Positioned.fill(
              child: Align(
                alignment: Alignment.centerRight,
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    for (final action in widget.actions)
                      SizedBox(
                        key: action.actionKey,
                        width: _actionWidth,
                        height: double.infinity,
                        child: Material(
                          color: action.color.withValues(alpha: 0.12),
                          child: InkWell(
                            onTap: () {
                              _close();
                              AppHaptics.selection();
                              action.onPressed();
                            },
                            child: Column(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Icon(
                                  action.icon,
                                  size: AppIconSize.compact,
                                  color: action.color,
                                ),
                                Text(
                                  action.label,
                                  maxLines: 1,
                                  style: Theme.of(context).textTheme.labelSmall
                                      ?.copyWith(
                                        color: action.color,
                                        fontWeight: FontWeight.w700,
                                        fontSize: 9,
                                        height: 1,
                                      ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                  ],
                ),
              ),
            ),
          AnimatedContainer(
            duration: _isDragging
                ? Duration.zero
                : const Duration(milliseconds: 170),
            curve: Curves.easeOutCubic,
            transform: Matrix4.translationValues(_offset, 0, 0),
            child: GestureDetector(
              behavior: HitTestBehavior.translucent,
              onHorizontalDragStart: (_) => setState(() => _isDragging = true),
              onHorizontalDragUpdate: (details) {
                setState(() {
                  _offset = (_offset + details.delta.dx).clamp(
                    -_actionsWidth,
                    0,
                  );
                });
              },
              onHorizontalDragEnd: (details) {
                final velocity = details.primaryVelocity ?? 0;
                setState(() {
                  _isDragging = false;
                  _offset = velocity < -250 || _offset < -_actionsWidth * 0.3
                      ? -_actionsWidth
                      : 0;
                });
              },
              child: Material(
                color: Theme.of(context).colorScheme.surface,
                child: widget.child,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

