bool _showsSpendableAvailability(v2_account.AccountRecord account) =>
    account.type == v2_account.AccountType.checking ||
    account.type == v2_account.AccountType.savings ||
    account.type == v2_account.AccountType.cash ||
    account.type == v2_account.AccountType.otherBanking;

class AccountsView extends StatelessWidget {
  const AccountsView({this.onOpenLedgerForAccount, super.key});

  final ValueChanged<String>? onOpenLedgerForAccount;

  @override
  Widget build(BuildContext context) {
    final store = FinanceDataStoreScope.watch(context);
    final accounts = store.activeAccountsInDisplayOrder;
    if (accounts.isEmpty) {
      return const AppCard(
        child: Text(
          'No accounts yet',
          style: TextStyle(fontWeight: FontWeight.w800),
        ),
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (final group in store.accountGroupsInDisplayOrder)
          if (accounts.any((account) => account.group == group))
            AccountGroupCard(
              group: group,
              accounts: accounts
                  .where((account) => account.group == group)
                  .toList(growable: false),
              store: store,
              onOpenLedgerForAccount: onOpenLedgerForAccount,
            ),
      ],
    );
  }
}

class AccountGroupCard extends StatelessWidget {
  const AccountGroupCard({
    required this.group,
    required this.accounts,
    required this.store,
    this.onOpenLedgerForAccount,
    super.key,
  });

  final v2_account.AccountGroup group;
  final List<v2_account.AccountRecord> accounts;
  final FinanceDataStore store;
  final ValueChanged<String>? onOpenLedgerForAccount;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final isCollapsed = store.preferences.collapsedAccountGroupNames.contains(
      group.name,
    );
    final label = store.accountGroupLabel(group);
    final balanceMinor = accounts
        .where((account) => account.includeInGroupBalance)
        .fold(
          0,
          (total, account) =>
              total + store.clearedBalanceForAccount(account.id),
        );
    final progress = accountGroupProgress(context, store, group);
    final showsLiabilitySummary = progress != null;
    final headerTextStyle = theme.textTheme.titleMedium?.copyWith(
      color: AppTheme.accentStrong,
      fontSize: 19,
      fontWeight: FontWeight.w700,
    );

    if (group == v2_account.AccountGroup.creditCards) {
      return _buildCreditCardGroup(
        context,
        isCollapsed: isCollapsed,
        label: label,
        balanceMinor: balanceMinor,
        progress: progress,
        headerTextStyle: headerTextStyle,
      );
    }

    return AppCard(
      padding: EdgeInsets.zero,
      borderRadius: 12,
      child: Padding(
        padding: const EdgeInsets.all(AppSpacing.md),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Tooltip(
              message: isCollapsed ? 'Expand $label' : 'Collapse $label',
              child: InkWell(
                key: ValueKey('account-group-${group.name}'),
                borderRadius: BorderRadius.circular(AppRadii.card),
                onTap: () {
                  AppHaptics.selection();
                  toggleAccountGroupCollapsed(
                    context,
                    group,
                    isCollapsed: isCollapsed,
                  );
                },
                onLongPress: () {
                  AppHaptics.longPressAction();
                  showAccountGroupActions(context, group);
                },
                child: _AccountGroupSummaryRow(
                  group: group,
                  label: label,
                  balanceMinor: balanceMinor,
                  currency: store.preferences.currency,
                  isCollapsed: isCollapsed,
                  headerTextStyle: headerTextStyle,
                ),
              ),
            ),
            AnimatedSize(
              duration: MediaQuery.of(context).disableAnimations
                  ? Duration.zero
                  : const Duration(milliseconds: 175),
              reverseDuration: MediaQuery.of(context).disableAnimations
                  ? Duration.zero
                  : const Duration(milliseconds: 145),
              curve: Curves.easeOutCubic,
              alignment: Alignment.topCenter,
              child: isCollapsed
                  ? const SizedBox.shrink()
                  : Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        if (showsLiabilitySummary) ...[
                          Padding(
                            padding: const EdgeInsets.only(
                              top: AppSpacing.xxs,
                              bottom: AppSpacing.sm,
                            ),
                            child: Text(
                              'Total Balance',
                              style: theme.textTheme.labelSmall?.copyWith(
                                color: theme.colorScheme.onSurfaceVariant,
                                fontWeight: FontWeight.w700,
                                letterSpacing: 0.15,
                              ),
                            ),
                          ),
                          progress,
                        ],
                        SizedBox(
                          height: showsLiabilitySummary
                              ? AppSpacing.md
                              : AppSpacing.xs,
                        ),
                        Divider(
                          height: 1,
                          color: theme.colorScheme.outlineVariant.withValues(
                            alpha: 0.55,
                          ),
                        ),
                        if (showsLiabilitySummary)
                          const SizedBox(height: AppSpacing.xs),
                        for (var index = 0; index < accounts.length; index++)
                          Dismissible(
                            key: ValueKey(
                              'account-swipe-${accounts[index].id}',
                            ),
                            direction: DismissDirection.horizontal,
                            dismissThresholds: const {
                              DismissDirection.startToEnd: 0.22,
                              DismissDirection.endToStart: 0.22,
                            },
                            background: SwipeActionBackground(
                              alignment: Alignment.centerLeft,
                              icon: AppIcon.transfer,
                              label: 'Expense  Income  Transfer',
                            ),
                            secondaryBackground: SwipeActionBackground(
                              alignment: Alignment.centerRight,
                              icon: AppIcon.edit,
                              label: 'Edit  Archive  Delete',
                              destructive: true,
                            ),
                            confirmDismiss: (direction) async {
                              AppHaptics.selection();
                              await showAccountOptions(
                                context,
                                accounts[index].id,
                                allowedActions:
                                    direction == DismissDirection.startToEnd
                                    ? const {'expense', 'income', 'transfer'}
                                    : const {'edit', 'archive', 'delete'},
                              );
                              return false;
                            },
                            child: AccountCard(
                              account: accounts[index],
                              transactions: store.transactions,
                              balanceMinor: store.clearedBalanceForAccount(
                                accounts[index].id,
                              ),
                              pendingEffectMinor:
                                  _showsSpendableAvailability(accounts[index])
                                  ? store.pendingEffectForAccount(
                                      accounts[index].id,
                                    )
                                  : null,
                              reservedMinor:
                                  _showsSpendableAvailability(accounts[index])
                                  ? store.reservedForAccount(accounts[index].id)
                                  : null,
                              availableToSpendMinor:
                                  _showsSpendableAvailability(accounts[index])
                                  ? store.availableToSpendForAccount(
                                      accounts[index].id,
                                    )
                                  : null,
                              currency: store.preferences.currency,
                              subtitle: lastAccountActivitySubtitle(
                                store,
                                accounts[index].id,
                              ),
                              balanceFontSize: 17,
                              framed: false,
                              padding: const EdgeInsets.symmetric(
                                vertical: AppSpacing.sm,
                              ),
                              leading: AccountAppearanceBadge(
                                accountType: accounts[index].type,
                                iconId: accounts[index].appearanceIconId,
                                accentId: accounts[index].appearanceAccentId,
                              ),
                              onTap: onOpenLedgerForAccount == null
                                  ? null
                                  : () => onOpenLedgerForAccount!(
                                      accounts[index].id,
                                    ),
                              onAvailabilityTap: () {
                                AppHaptics.selection();
                                unawaited(
                                  showAccountDetailsSheet(
                                    context,
                                    accounts[index].id,
                                  ),
                                );
                              },
                              onLongPress: () {
                                AppHaptics.longPressAction();
                                showAccountOptions(context, accounts[index].id);
                              },
                            ),
                          ),
                      ],
                    ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildCreditCardGroup(
    BuildContext context, {
    required bool isCollapsed,
    required String label,
    required int balanceMinor,
    required Widget? progress,
    required TextStyle? headerTextStyle,
  }) {
    final animationsDisabled = MediaQuery.of(context).disableAnimations;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        AppCard(
          padding: EdgeInsets.zero,
          borderRadius: 14,
          child: Tooltip(
            message: isCollapsed ? 'Expand $label' : 'Collapse $label',
            child: InkWell(
              key: ValueKey('account-group-${group.name}'),
              borderRadius: BorderRadius.circular(14),
              onTap: () {
                AppHaptics.selection();
                toggleAccountGroupCollapsed(
                  context,
                  group,
                  isCollapsed: isCollapsed,
                );
              },
              onLongPress: () {
                AppHaptics.longPressAction();
                showAccountGroupActions(context, group);
              },
              child: Padding(
                padding: const EdgeInsets.all(AppSpacing.md),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    _AccountGroupSummaryRow(
                      group: group,
                      label: label,
                      balanceMinor: balanceMinor,
                      currency: store.preferences.currency,
                      isCollapsed: isCollapsed,
                      headerTextStyle: headerTextStyle,
                    ),
                    AnimatedSize(
                      duration: animationsDisabled
                          ? Duration.zero
                          : const Duration(milliseconds: 175),
                      reverseDuration: animationsDisabled
                          ? Duration.zero
                          : const Duration(milliseconds: 145),
                      curve: Curves.easeOutCubic,
                      alignment: Alignment.topCenter,
                      child: isCollapsed || progress == null
                          ? const SizedBox.shrink()
                          : Padding(
                              padding: const EdgeInsets.only(
                                top: AppSpacing.sm,
                              ),
                              child: progress,
                            ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
        AnimatedSize(
          duration: animationsDisabled
              ? Duration.zero
              : const Duration(milliseconds: 175),
          reverseDuration: animationsDisabled
              ? Duration.zero
              : const Duration(milliseconds: 145),
          curve: Curves.easeOutCubic,
          alignment: Alignment.topCenter,
          child: isCollapsed
              ? const SizedBox.shrink()
              : Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const SizedBox(height: AppSpacing.xs),
                    for (var index = 0; index < accounts.length; index++) ...[
                      _buildCreditCardAccount(context, accounts[index]),
                      if (index != accounts.length - 1)
                        const SizedBox(height: AppSpacing.xs),
                    ],
                  ],
                ),
        ),
      ],
    );
  }

  Widget _buildCreditCardAccount(
    BuildContext context,
    v2_account.AccountRecord account,
  ) {
    const radius = 14.0;
    return ClipRRect(
      borderRadius: BorderRadius.circular(radius),
      child: Dismissible(
        key: ValueKey('account-swipe-${account.id}'),
        direction: DismissDirection.horizontal,
        dismissThresholds: const {
          DismissDirection.startToEnd: 0.22,
          DismissDirection.endToStart: 0.22,
        },
        background: SwipeActionBackground(
          alignment: Alignment.centerLeft,
          icon: AppIcon.transfer,
          label: 'Expense  Income  Transfer',
        ),
        secondaryBackground: SwipeActionBackground(
          alignment: Alignment.centerRight,
          icon: AppIcon.edit,
          label: 'Edit  Archive  Delete',
          destructive: true,
        ),
        confirmDismiss: (direction) async {
          AppHaptics.selection();
          await showAccountOptions(
            context,
            account.id,
            allowedActions: direction == DismissDirection.startToEnd
                ? const {'expense', 'income', 'transfer'}
                : const {'edit', 'archive', 'delete'},
          );
          return false;
        },
        child: AccountCard(
          account: account,
          transactions: store.transactions,
          nextScheduledPaymentDueDate: store.nextCreditCardPaymentDueDate(
            account.id,
          ),
          balanceMinor: store.clearedBalanceForAccount(account.id),
          metricBalanceMinor:
              store.clearedBalanceForAccount(account.id) +
              store.pendingEffectForAccount(account.id),
          creditInsightsBalanceMinor:
              store.clearedBalanceForAccount(account.id) +
              store.pendingEffectForAccount(account.id),
          currency: store.preferences.currency,
          subtitle: lastAccountActivitySubtitle(store, account.id),
          balanceFontSize: 17,
          framed: true,
          borderRadius: radius,
          showNavigationChevron: true,
          metricLeadingIndent: 58,
          padding: const EdgeInsets.all(AppSpacing.md),
          leading: CreditCardAppearanceBadge(
            iconId: account.creditCardIconId,
            accentId: account.creditCardAccentId,
          ),
          onTap: onOpenLedgerForAccount == null
              ? null
              : () => onOpenLedgerForAccount!(account.id),
          onLongPress: () {
            AppHaptics.longPressAction();
            showAccountOptions(context, account.id);
          },
        ),
      ),
    );
  }
}

