String lastAccountActivitySubtitle(FinanceDataStore store, String accountId) {
  final activity =
      store.transactions
          .where(
            (transaction) =>
                !transaction.isDeleted &&
                (transaction.accountId == accountId ||
                    transaction.transferAccountId == accountId),
          )
          .toList(growable: false)
        ..sort((a, b) => b.date.compareTo(a.date));
  if (activity.isEmpty) return 'No transactions yet';

  final latest = activity.first;
  final payee = latest.payee.trim().isEmpty
      ? transactionTypeLabel(latest.type)
      : latest.payee.trim();
  return '$payee · ${compactDate(latest.date)}';
}

Widget? accountGroupProgress(
  BuildContext context,
  FinanceDataStore store,
  v2_account.AccountGroup group,
) {
  switch (group) {
    case v2_account.AccountGroup.creditCards:
      final limit = store.creditLimitMinorForGroup(group);
      if (limit <= 0) return null;
      final used = store.creditUsedMinorForGroup(group);
      final available = store.creditAvailableMinorForGroup(group);
      return AccountGroupProgressStrip(
        label:
            'Credit Available ${money(available, store.preferences.currency)} of ${money(limit, store.preferences.currency)}',
        progress: used / limit,
        isOver: used > limit,
        showPercentage: true,
        isCreditUtilization: true,
      );
    case v2_account.AccountGroup.loans:
      final original = store.originalLoanAmountMinorForGroup(group);
      if (original <= 0) return null;
      final remaining = store.remainingLoanMinorForGroup(group);
      final rawPaidDown = original - remaining;
      final paidDown = rawPaidDown < 0
          ? 0
          : rawPaidDown > original
          ? original
          : rawPaidDown;
      return AccountGroupProgressStrip(
        label:
            'Paid down ${money(paidDown, store.preferences.currency)} of ${money(original, store.preferences.currency)}',
        progress: paidDown / original,
      );
    case v2_account.AccountGroup.banking:
    case v2_account.AccountGroup.cash:
      return null;
  }
}

class AccountGroupProgressStrip extends StatelessWidget {
  const AccountGroupProgressStrip({
    required this.label,
    required this.progress,
    this.isOver = false,
    this.showPercentage = false,
    this.isCreditUtilization = false,
    super.key,
  });

  final String label;
  final double progress;
  final bool isOver;
  final bool showPercentage;
  final bool isCreditUtilization;

  @override
  Widget build(BuildContext context) {
    final value = progress.clamp(0.0, 1.0).toDouble();
    final fillColor = isCreditUtilization
        ? creditUtilizationFillColor(
            progress,
            brightness: Theme.of(context).brightness,
          )
        : isOver
        ? AppColors.danger
        : AppColors.accent;
    return Padding(
      padding: EdgeInsets.zero,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            softWrap: false,
            style: Theme.of(context).textTheme.bodySmall?.copyWith(
              color: Theme.of(context).colorScheme.onSurfaceVariant,
              fontFeatures: const [AppTextStyles.tabularFigures],
            ),
          ),
          const SizedBox(height: AppSpacing.xxs),
          Row(
            children: [
              Expanded(
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(AppRadii.pill),
                  child: SizedBox(
                    height: 4,
                    child: LinearProgressIndicator(
                      value: value,
                      backgroundColor: Theme.of(
                        context,
                      ).colorScheme.outlineVariant.withValues(alpha: 0.62),
                      color: fillColor.withValues(alpha: 0.82),
                    ),
                  ),
                ),
              ),
              if (showPercentage) ...[
                const SizedBox(width: AppSpacing.sm),
                ConstrainedBox(
                  constraints: const BoxConstraints(
                    minWidth: creditUtilizationLabelMinWidth,
                  ),
                  child: Text(
                    '${(progress * 100).round()}% utilized',
                    maxLines: 1,
                    softWrap: false,
                    textAlign: TextAlign.right,
                    style: Theme.of(context).textTheme.bodySmall?.copyWith(
                      color: Theme.of(context).colorScheme.onSurfaceVariant,
                      fontWeight: FontWeight.w700,
                      fontFeatures: const [AppTextStyles.tabularFigures],
                    ),
                  ),
                ),
              ],
            ],
          ),
        ],
      ),
    );
  }
}

Future<void> toggleAccountGroupCollapsed(
  BuildContext context,
  v2_account.AccountGroup group, {
  required bool isCollapsed,
}) async {
  final store = FinanceDataStoreScope.read(context);
  final collapsedNames = {...store.preferences.collapsedAccountGroupNames};
  if (isCollapsed) {
    collapsedNames.remove(group.name);
  } else {
    collapsedNames.add(group.name);
  }
  await store.savePreferences(
    store.preferences.copyWith(collapsedAccountGroupNames: collapsedNames),
  );
}

Future<void> showAccountGroupActions(
  BuildContext context,
  v2_account.AccountGroup group,
) async {
  final store = FinanceDataStoreScope.read(context);
  final groups = store.accountGroupsInDisplayOrder;
  final groupIndex = groups.indexOf(group);
  final canMoveUp = groupIndex > 0;
  final canMoveDown = groupIndex >= 0 && groupIndex < groups.length - 1;
  final action = await showModalBottomSheet<String>(
    context: context,
    isScrollControlled: true,
    showDragHandle: true,
    builder: (sheetContext) => SafeArea(
      child: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: Icon(AppIcon.edit),
              title: Text('Rename'),
              onTap: () => Navigator.pop(sheetContext, 'rename'),
            ),
            ListTile(
              enabled: canMoveUp,
              leading: Icon(AppIcon.arrowUp),
              title: Text('Move Up'),
              onTap: canMoveUp
                  ? () => Navigator.pop(sheetContext, 'moveUp')
                  : null,
            ),
            ListTile(
              enabled: canMoveDown,
              leading: Icon(AppIcon.arrowDown),
              title: const Text('Move Down'),
              onTap: canMoveDown
                  ? () => Navigator.pop(sheetContext, 'moveDown')
                  : null,
            ),
          ],
        ),
      ),
    ),
  );

  if (!context.mounted || action == null) return;
  switch (action) {
    case 'rename':
      await showRenameAccountGroupDialog(context, group);
    case 'moveUp':
      await store.moveAccountGroup(group: group, direction: -1);
    case 'moveDown':
      await store.moveAccountGroup(group: group, direction: 1);
  }
}

Future<void> showRenameAccountGroupDialog(
  BuildContext context,
  v2_account.AccountGroup group,
) async {
  final store = FinanceDataStoreScope.read(context);
  final controller = TextEditingController(
    text: store.accountGroupLabel(group),
  );
  final label = await showDialog<String>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: const Text('Rename account group'),
      content: TextField(
        controller: controller,
        autofocus: true,
        textCapitalization: TextCapitalization.words,
        decoration: InputDecoration(
          labelText: 'Group name',
          hintText: group.defaultLabel,
        ),
        onSubmitted: (value) => Navigator.pop(dialogContext, value),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: () => Navigator.pop(dialogContext, controller.text),
          child: const Text('Save'),
        ),
      ],
    ),
  );

  if (!context.mounted || label == null) return;
  await store.renameAccountGroup(group: group, label: label);
}

class LedgerDrillDownFilter {
  const LedgerDrillDownFilter({
    required this.label,
    required this.periodLabel,
    required this.start,
    required this.endExclusive,
    required this.icon,
    this.accountId,
    this.categoryId,
    this.payee,
    this.transactionType,
    this.uncategorizedExpensesOnly = false,
  });

  final String label;
  final String periodLabel;
  final DateTime start;
  final DateTime endExclusive;
  final IconData icon;
  final String? accountId;
  final String? categoryId;
  final String? payee;
  final TransactionType? transactionType;
  final bool uncategorizedExpensesOnly;

  bool matches(TransactionRecord transaction) {
    if (transaction.date.isBefore(start) ||
        !transaction.date.isBefore(endExclusive)) {
      return false;
    }
    if (transactionType != null && transaction.type != transactionType) {
      return false;
    }
    if (accountId != null && transaction.accountId != accountId) return false;
    if (uncategorizedExpensesOnly &&
        transaction.effectiveCategoryAllocations.isNotEmpty) {
      return false;
    }
    if (payee != null &&
        normalizeManagedPayee(transaction.payee) !=
            normalizeManagedPayee(payee!)) {
      return false;
    }
    return true;
  }
}

const _ledgerGoalsTypeFilter = 'goals';
const _ledgerFundsTypeFilter = 'funds';

class LedgerView extends StatefulWidget {
  const LedgerView({
    this.initialAccountFilterId,
    this.initialManagementFilter,
    this.initialDrillDownFilter,
    this.initialPendingTransactionIds,
    this.showPendingSummary = true,
    this.enableMainFilterBackSwipe = false,
    this.contentPadding = EdgeInsets.zero,
    super.key,
  });

  final String? initialAccountFilterId;
  final ManagementLedgerFilter? initialManagementFilter;
  final LedgerDrillDownFilter? initialDrillDownFilter;
  final Set<String>? initialPendingTransactionIds;
  final bool showPendingSummary;
  final bool enableMainFilterBackSwipe;
  final EdgeInsetsGeometry contentPadding;

  @override
  State<LedgerView> createState() => _LedgerViewState();
}

class _LedgerViewState extends State<LedgerView> {
  final _searchFocusNode = FocusNode(
    debugLabel: 'ledger-search',
    skipTraversal: true,
  );
  var query = '';
  var typeFilterName = '';
  var accountFilterId = '';
  var categoryFilterId = '';
  var dateFilter = LedgerDateFilter.all;
  DateTimeRange? customDateRange;
  ManagementLedgerFilter? managementFilter;
  LedgerDrillDownFilter? drillDownFilter;
  final _collapsedMonthKeys = <String>{};
  final _monthAnchors = <String, GlobalKey>{};

  @override
  void initState() {
    super.initState();
    accountFilterId = widget.initialAccountFilterId ?? '';
    managementFilter = widget.initialManagementFilter;
    drillDownFilter = widget.initialDrillDownFilter;
  }

  @override
  void didUpdateWidget(covariant LedgerView oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.initialAccountFilterId != oldWidget.initialAccountFilterId &&
        widget.initialAccountFilterId != null) {
      accountFilterId = widget.initialAccountFilterId!;
    }
    if (widget.initialManagementFilter != oldWidget.initialManagementFilter) {
      managementFilter = widget.initialManagementFilter;
    }
    if (widget.initialDrillDownFilter != oldWidget.initialDrillDownFilter) {
      drillDownFilter = widget.initialDrillDownFilter;
    }
  }

  @override
  void dispose() {
    _searchFocusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final store = FinanceDataStoreScope.watch(context);
    final activeAccounts = store.activeAccountsInDisplayOrder;
    final activeCategories = store.categories
        .where((category) => category.isVisible)
        .toList(growable: false);
    final accountsById = {
      for (final account in store.accounts) account.id: account,
    };
    final categoriesById = {
      for (final category in store.categories) category.id: category,
    };
    final goalsById = {for (final goal in store.goals) goal.id: goal};
    final fundsById = {for (final fund in store.funds) fund.id: fund};
    final singleAccountId = accountFilterId.isNotEmpty
        ? accountFilterId
        : drillDownFilter?.accountId;
    final singleAccount = singleAccountId == null
        ? null
        : accountsById[singleAccountId];
    final runningBalances = singleAccount == null
        ? null
        : calculateAccountRunningBalances(
            account: singleAccount,
            transactions: store.transactions,
            goalFundingEvents: store.goalFundingEvents,
          );
    final showRunningBalance =
        singleAccount != null && store.preferences.showRunningBalance;
    final now = DateTime.now();
    final managementTransactionIds = managementFilter == null
        ? null
        : ManagementLedgerIndex.build(
            transactions: store.transactions,
            accounts: store.accounts,
            categories: store.categories,
            now: now,
          ).transactionIdsFor(managementFilter!);
    final normalizedQuery = query.trim().toLowerCase();
    String? reservationContainerNameFor(TransactionRecord transaction) {
      final containerId = transaction.reservationContainerId;
      if (containerId == null || containerId.isEmpty) return null;
      return switch (transaction.reservationContainerType) {
        ReservationContainerType.goal => goalsById[containerId]?.name,
        ReservationContainerType.fund => fundsById[containerId]?.name,
        null => null,
      };
    }

    final requestedCategoryId = categoryFilterId.isNotEmpty
        ? categoryFilterId
        : drillDownFilter?.categoryId?.isNotEmpty == true
        ? drillDownFilter!.categoryId!
        : managementFilter?.kind == ManagementLedgerFilterKind.category
        ? managementFilter!.value
        : '';
    final categoryScope = requestedCategoryId.isEmpty
        ? null
        : LedgerCategoryScope.fromCategory(
            store.categories,
            requestedCategoryId,
          );
    final unprojectedTransactions =
        store.transactions
            .where((transaction) => !transaction.isDeleted)
            .where(
              (transaction) =>
                  widget.initialPendingTransactionIds == null ||
                  (transaction.status ==
                          v2_transaction.TransactionStatus.pending &&
                      widget.initialPendingTransactionIds!.contains(
                        transaction.id,
                      )),
            )
            .where(
              (transaction) =>
                  managementTransactionIds == null ||
                  managementTransactionIds.contains(transaction.id),
            )
            .where(
              (transaction) =>
                  drillDownFilter == null ||
                  drillDownFilter!.matches(transaction),
            )
            .where(
              (transaction) => transactionMatchesSearch(
                transaction,
                normalizedQuery,
                accountName: accountsById[transaction.accountId]?.name,
                categoryName: transaction.categoryId == null
                    ? null
                    : categoriesById[transaction.categoryId]?.name,
                reservationContainerName: reservationContainerNameFor(
                  transaction,
                ),
              ),
            )
            .where(
              (transaction) => transactionMatchesLedgerFilters(
                transaction,
                typeFilterName: typeFilterName,
                accountFilterId: accountFilterId,
                // Category matching is resolved by the shared allocation
                // projection below so parent scopes and split amounts agree.
                categoryFilterId: '',
                dateFilter: dateFilter,
                customDateRange: customDateRange,
                now: now,
              ),
            )
            .toList()
          ..sort(compareTransactionsNewestFirst);
    final transactions = projectLedgerTransactions(
      unprojectedTransactions,
      categoryScope: categoryScope,
    );
    final pendingSummary = summarizePendingLedgerTransactions(transactions);
    final reservationActivities =
        projectLedgerReservationActivities(
              goals: store.goals,
              funds: store.funds,
              operations: store.reservationOperations,
              transactions: store.transactions,
              scheduledTransactions: store.scheduledTransactions,
            )
            .where((activity) {
              if (widget.initialPendingTransactionIds != null ||
                  managementFilter != null ||
                  drillDownFilter != null ||
                  categoryFilterId.isNotEmpty) {
                return false;
              }
              final expectedType =
                  activity.containerType == ReservationContainerType.goal
                  ? _ledgerGoalsTypeFilter
                  : _ledgerFundsTypeFilter;
              if (typeFilterName.isNotEmpty && typeFilterName != expectedType) {
                return false;
              }
              if (accountFilterId.isNotEmpty &&
                  activity.fundingAccountId != accountFilterId) {
                return false;
              }
              if (!dateMatchesLedgerFilter(
                activity.effectiveDate,
                dateFilter: dateFilter,
                customDateRange: customDateRange,
                now: now,
              )) {
                return false;
              }
              if (normalizedQuery.isEmpty) return true;
              final accountName =
                  accountsById[activity.fundingAccountId]?.name ?? '';
              final action = activity.isAllocation
                  ? 'allocated reserve'
                  : 'returned';
              final containerKind =
                  activity.containerType == ReservationContainerType.goal
                  ? 'goal'
                  : 'fund';
              return '$action ${activity.containerName} $containerKind '
                      '$accountName ${activity.note}'
                  .toLowerCase()
                  .contains(normalizedQuery);
            })
            .toList(growable: false);
    final goalFundingEvents =
        store.goalFundingEvents
            .where((event) => event.isActive)
            .where((event) => !event.isMigrationEvent)
            .where(
              (event) =>
                  widget.initialPendingTransactionIds == null &&
                  managementFilter == null &&
                  drillDownFilter == null &&
                  (typeFilterName.isEmpty ||
                      typeFilterName == _ledgerGoalsTypeFilter) &&
                  categoryFilterId.isEmpty &&
                  (accountFilterId.isEmpty ||
                      event.sourceAccountId == accountFilterId) &&
                  dateMatchesLedgerFilter(
                    event.date,
                    dateFilter: dateFilter,
                    customDateRange: customDateRange,
                    now: now,
                  ),
            )
            .where((event) {
              if (normalizedQuery.isEmpty) return true;
              final goalNames = event.allocations
                  .map(
                    (allocation) => store.goals
                        .where((goal) => goal.id == allocation.goalId)
                        .firstOrNull
                        ?.name,
                  )
                  .whereType<String>()
                  .join(' ');
              final accountName =
                  accountsById[event.sourceAccountId]?.name ?? '';
              return 'funded goals ${event.note} $goalNames $accountName'
                  .toLowerCase()
                  .contains(normalizedQuery);
            })
            .toList(growable: false)
          ..sort((a, b) => b.date.compareTo(a.date));
    final hasFilters =
        typeFilterName.isNotEmpty ||
        accountFilterId.isNotEmpty ||
        categoryFilterId.isNotEmpty ||
        dateFilter != LedgerDateFilter.all ||
        managementFilter != null ||
        drillDownFilter != null;
    final selectedTypeLabel = ledgerTypeFilterLabel(typeFilterName);
    final selectedAccountLabel = accountFilterId.isEmpty
        ? 'All Accounts'
        : accountsById[accountFilterId]?.name ?? 'Account';
    final selectedCategoryLabel = categoryFilterId.isEmpty
        ? 'All Categories'
        : categoriesById[categoryFilterId]?.name ?? 'Category';
    final selectedDateLabel = dateFilter == LedgerDateFilter.all
        ? 'Any Date'
        : dateFilter == LedgerDateFilter.custom && customDateRange != null
        ? '${shortMonthDay(customDateRange!.start)}–${shortMonthDay(customDateRange!.end)}'
        : ledgerDateFilterLabel(dateFilter);
    final activeFilterCount = [
      typeFilterName.isNotEmpty,
      accountFilterId.isNotEmpty,
      categoryFilterId.isNotEmpty,
      dateFilter != LedgerDateFilter.all,
    ].where((isActive) => isActive).length;
    final transactionsByMonth = <DateTime, List<LedgerTransactionProjection>>{};
    for (final projection in transactions) {
      final month = DateTime(
        projection.transaction.date.year,
        projection.transaction.date.month,
      );
      transactionsByMonth.putIfAbsent(month, () => []).add(projection);
    }
    final fundingByMonth = <DateTime, List<GoalFundingEventRecord>>{};
    for (final event in goalFundingEvents) {
      final month = DateTime(event.date.year, event.date.month);
      fundingByMonth.putIfAbsent(month, () => []).add(event);
    }
    final reservationsByMonth =
        <DateTime, List<LedgerReservationActivityProjection>>{};
    for (final activity in reservationActivities) {
      final month = DateTime(
        activity.effectiveDate.year,
        activity.effectiveDate.month,
      );
      reservationsByMonth.putIfAbsent(month, () => []).add(activity);
    }
    final visibleMonths = {
      ...transactionsByMonth.keys,
      ...fundingByMonth.keys,
      ...reservationsByMonth.keys,
    }.toList(growable: false)..sort((a, b) => b.compareTo(a));
    for (final month in visibleMonths) {
      _monthAnchors.putIfAbsent(ledgerMonthKey(month), () => GlobalKey());
    }

    final ledger = Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (accountFilterId.isNotEmpty &&
            accountsById[accountFilterId] != null) ...[
          Padding(
            padding: const EdgeInsets.fromLTRB(4, 0, 4, 10),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        accountsById[accountFilterId]!.name,
                        style: Theme.of(context).textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900),
                      ),
                      Text(
                        'Balance',
                        style: Theme.of(context).textTheme.bodySmall?.copyWith(
                          color: Theme.of(context).colorScheme.onSurfaceVariant,
                        ),
                      ),
                      if (accountBalancePresentation(
                        accountsById[accountFilterId]!.type,
                        store.clearedBalanceForAccount(accountFilterId),
                      ).needsAttention)
                        Text(
                          'Needs attention',
                          key: const ValueKey('ledger-account-needs-attention'),
                          style: Theme.of(context).textTheme.labelSmall
                              ?.copyWith(
                                color: AppColors.danger,
                                fontWeight: FontWeight.w800,
                              ),
                        ),
                    ],
                  ),
                ),
                AccountBalanceText(
                  accountType: accountsById[accountFilterId]!.type,
                  signedBalanceMinor: store.clearedBalanceForAccount(
                    accountFilterId,
                  ),
                  currency: store.preferences.currency,
                  fontSize: 18,
                  fontWeight: FontWeight.w900,
                ),
              ],
            ),
          ),
        ],
        if (managementFilter case final filter?) ...[
          Container(
            key: const ValueKey('ledger-management-filter-context'),
            margin: const EdgeInsets.only(bottom: AppSpacing.sm),
            padding: const EdgeInsets.symmetric(
              horizontal: AppSpacing.md,
              vertical: AppSpacing.sm,
            ),
            decoration: BoxDecoration(
              color: Theme.of(
                context,
              ).colorScheme.primaryContainer.withValues(alpha: 0.46),
              borderRadius: BorderRadius.circular(AppRadii.control),
              border: Border.all(
                color: Theme.of(
                  context,
                ).colorScheme.primary.withValues(alpha: 0.16),
              ),
            ),
            child: Row(
              children: [
                Icon(
                  filter.kind == ManagementLedgerFilterKind.category
                      ? AppIcon.category
                      : AppIcon.payee,
                  size: AppIconSize.inline,
                  color: Theme.of(context).colorScheme.primary,
                ),
                const SizedBox(width: AppSpacing.sm),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        '${filter.kind == ManagementLedgerFilterKind.category ? 'Category' : 'Payee'}: ${filter.label}',
                        key: const ValueKey('ledger-management-filter-label'),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: Theme.of(context).textTheme.labelLarge?.copyWith(
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      Text(
                        'Period: Last 12 Months',
                        style: Theme.of(context).textTheme.bodySmall?.copyWith(
                          color: Theme.of(context).colorScheme.onSurfaceVariant,
                        ),
                      ),
                    ],
                  ),
                ),
                TextButton(
                  onPressed: () => setState(() => managementFilter = null),
                  child: const Text('Clear Filter'),
                ),
              ],
            ),
          ),
        ],
        if (drillDownFilter case final filter?) ...[
          Builder(
            builder: (context) {
              final theme = Theme.of(context);
              final isDark = theme.brightness == Brightness.dark;
              final contextAccent = isDark
                  ? Color.lerp(AppColors.info, Colors.white, 0.24)!
                  : AppColors.info;
              final contextSurface = Color.alphaBlend(
                AppColors.info.withValues(alpha: isDark ? 0.16 : 0.09),
                theme.colorScheme.surface,
              );

              return Container(
                key: const ValueKey('ledger-report-filter-context'),
                margin: const EdgeInsets.only(bottom: AppSpacing.sm),
                padding: const EdgeInsets.symmetric(
                  horizontal: AppSpacing.md,
                  vertical: AppSpacing.sm,
                ),
                decoration: BoxDecoration(
                  color: contextSurface,
                  borderRadius: BorderRadius.circular(AppRadii.control),
                  border: Border.all(
                    color: contextAccent.withValues(
                      alpha: isDark ? 0.34 : 0.24,
                    ),
                  ),
                ),
                child: Row(
                  children: [
                    Icon(
                      filter.icon,
                      size: AppIconSize.inline,
                      color: contextAccent,
                    ),
                    const SizedBox(width: AppSpacing.sm),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            filter.label,
                            key: const ValueKey('ledger-report-filter-label'),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: Theme.of(context).textTheme.labelLarge
                                ?.copyWith(fontWeight: FontWeight.w800),
                          ),
                          Text(
                            filter.periodLabel,
                            style: Theme.of(context).textTheme.bodySmall
                                ?.copyWith(
                                  color: Theme.of(
                                    context,
                                  ).colorScheme.onSurfaceVariant,
                                ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        ],
        Row(
          children: [
            Expanded(
              child: SizedBox(
                height: 44,
                child: TextField(
                  focusNode: _searchFocusNode,
                  decoration: InputDecoration(
                    hintText: 'Search',
                    prefixIcon: Icon(AppIcon.search, size: AppIconSize.inline),
                    isDense: true,
                    contentPadding: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 9,
                    ),
                    filled: true,
                    fillColor: Theme.of(context)
                        .colorScheme
                        .surfaceContainerHighest
                        .withValues(alpha: 0.55),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(16),
                      borderSide: BorderSide.none,
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(16),
                      borderSide: BorderSide.none,
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(16),
                      borderSide: BorderSide(
                        color: Theme.of(context).colorScheme.primary,
                        width: 1.2,
                      ),
                    ),
                  ),
                  onTapOutside: (_) => _dismissSearchFocus(),
                  onChanged: (value) => setState(() => query = value),
                ),
              ),
            ),
            const SizedBox(width: AppSpacing.sm),
            SizedBox.square(
              dimension: 44,
              child: IconButton(
                key: const ValueKey('ledger-filter-button'),
                tooltip: activeFilterCount == 0
                    ? 'Filters'
                    : 'Filters active ($activeFilterCount)',
                onPressed: () async {
                  _dismissSearchFocus();
                  await showLedgerFilters(
                    context: context,
                    activeAccounts: activeAccounts,
                    activeCategories: activeCategories,
                    selectedTypeLabel: selectedTypeLabel,
                    selectedAccountLabel: selectedAccountLabel,
                    selectedCategoryLabel: selectedCategoryLabel,
                    selectedDateLabel: selectedDateLabel,
                    visibleMonths: visibleMonths,
                  );
                  if (mounted) _dismissSearchFocus();
                },
                icon: Icon(AppIcon.filter, size: AppIconSize.form),
                style: IconButton.styleFrom(
                  backgroundColor: activeFilterCount == 0
                      ? Theme.of(context).colorScheme.surfaceContainerHighest
                            .withValues(alpha: 0.55)
                      : Color.alphaBlend(
                          AppColors.accent.withValues(
                            alpha:
                                Theme.of(context).brightness == Brightness.dark
                                ? 0.26
                                : 0.17,
                          ),
                          Theme.of(context).colorScheme.surface,
                        ),
                  foregroundColor: activeFilterCount == 0
                      ? Theme.of(context).colorScheme.onSurfaceVariant
                      : Theme.of(context).brightness == Brightness.dark
                      ? Color.lerp(AppColors.accent, Colors.white, 0.18)
                      : AppColors.accent,
                  side: activeFilterCount == 0
                      ? BorderSide.none
                      : BorderSide(
                          color: AppColors.accent.withValues(
                            alpha:
                                Theme.of(context).brightness == Brightness.dark
                                ? 0.58
                                : 0.44,
                          ),
                          width: 1.15,
                        ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
              ),
            ),
            const SizedBox(width: AppSpacing.sm),
            SizedBox.square(
              dimension: 44,
              child: IconButton(
                tooltip: 'Clear filters',
                onPressed: hasFilters ? clearFilters : null,
                icon: Icon(AppIcon.clearFilter, size: AppIconSize.form),
                style: IconButton.styleFrom(
                  backgroundColor: Theme.of(
                    context,
                  ).colorScheme.surfaceContainerHighest.withValues(alpha: 0.55),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
              ),
            ),
          ],
        ),
        if (widget.showPendingSummary && !pendingSummary.isEmpty) ...[
          const SizedBox(height: AppSpacing.sm),
          _PendingTransactionsCard(
            summary: pendingSummary,
            currency: store.preferences.currency,
            onTap: () {
              _dismissSearchFocus();
              AppHaptics.navigation();
              Navigator.of(context).push(
                MaterialPageRoute<void>(
                  builder: (_) => FinanceDataStoreScope(
                    store: store,
                    child: PendingLedgerScreen(
                      transactionIds: pendingSummary.transactionIds,
                      accountId: singleAccountId,
                    ),
                  ),
                ),
              );
            },
          ),
        ],
        const SizedBox(height: 12),
        if (transactions.isEmpty &&
            goalFundingEvents.isEmpty &&
            reservationActivities.isEmpty)
          AppCard(
            child: Center(
              child: Text(
                'No activities match',
                style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                  color: Theme.of(context).colorScheme.onSurfaceVariant,
                ),
              ),
            ),
          )
        else
          for (final month in visibleMonths) ...[
            LedgerMonthSection(
              key: _monthAnchors[ledgerMonthKey(month)],
              month: month,
              transactions: transactionsByMonth[month] ?? const [],
              goalFundingEvents: fundingByMonth[month] ?? const [],
              reservationActivities: reservationsByMonth[month] ?? const [],
              store: store,
              accountsById: accountsById,
              categoriesById: categoriesById,
              scopedAccountId: singleAccountId,
              reservePendingIndicatorSpace: !pendingSummary.isEmpty,
              runningBalances: showRunningBalance ? runningBalances : null,
              isCollapsed: _collapsedMonthKeys.contains(ledgerMonthKey(month)),
              onDismissFocus: _dismissSearchFocus,
              onToggle: () {
                _dismissSearchFocus();
                AppHaptics.selection();
                setState(() {
                  final key = ledgerMonthKey(month);
                  if (!_collapsedMonthKeys.add(key)) {
                    _collapsedMonthKeys.remove(key);
                  }
                });
              },
            ),
            const SizedBox(height: AppSpacing.sm),
          ],
      ],
    );
    return _FilteredLedgerBackSwipe(
      enabled:
          Theme.of(context).platform == TargetPlatform.iOS &&
          widget.enableMainFilterBackSwipe &&
          activeFilterCount > 0,
      onCommitted: clearFilters,
      child: Padding(padding: widget.contentPadding, child: ledger),
    );
  }

  void clearFilters() {
    final hadFilters =
        typeFilterName.isNotEmpty ||
        accountFilterId.isNotEmpty ||
        categoryFilterId.isNotEmpty ||
        dateFilter != LedgerDateFilter.all ||
        managementFilter != null ||
        drillDownFilter != null;
    if (!hadFilters) return;
    AppHaptics.navigation();
    _dismissSearchFocus();
    setState(() {
      typeFilterName = '';
      accountFilterId = '';
      categoryFilterId = '';
      dateFilter = LedgerDateFilter.all;
      customDateRange = null;
      managementFilter = null;
    });
  }

  void _dismissSearchFocus() {
    _searchFocusNode.unfocus(disposition: UnfocusDisposition.scope);
    FocusManager.instance.primaryFocus?.unfocus(
      disposition: UnfocusDisposition.scope,
    );
  }

  Future<void> showLedgerFilters({
    required BuildContext context,
    required List<v2_account.AccountRecord> activeAccounts,
    required List<v2_category.CategoryRecord> activeCategories,
    required String selectedTypeLabel,
    required String selectedAccountLabel,
    required String selectedCategoryLabel,
    required String selectedDateLabel,
    required List<DateTime> visibleMonths,
  }) async {
