                  _LedgerFilterSummaryRow(
                    rowKey: const ValueKey('ledger-jump-month'),
                    icon: AppIcon.event,
                    label: 'Jump to Month',
                    value: monthLabel(visibleMonths.first),
                    showDivider: false,
                    onTap: () {
                      Navigator.pop(sheetContext);
                      WidgetsBinding.instance.addPostFrameCallback((_) async {
                        final value = await showLedgerSelectionSheet<String>(
                          context: context,
                          title: 'Jump to Month',
                          selectedValue: '',
                          items: [
                            for (final month in visibleMonths)
                              (
                                value: ledgerMonthKey(month),
                                label: monthLabel(month),
                                icon: AppIcon.event,
                                detail: null,
                              ),
                          ],
                        );
                        if (value == null || !mounted) return;
                        final anchor = _monthAnchors[value]?.currentContext;
                        if (anchor == null || !anchor.mounted) return;
                        Scrollable.ensureVisible(
                          anchor,
                          duration: const Duration(milliseconds: 280),
                          curve: Curves.easeOutCubic,
                          alignment: 0.08,
                        );
                      });
                    },
                  ),
                ],
                const SizedBox(height: AppSpacing.md),
                TextButton.icon(
                  onPressed: hasUserFilters
                      ? () {
                          clearFilters();
                          Navigator.pop(sheetContext);
                        }
                      : null,
                  icon: Icon(AppIcon.clearFilter),
                  label: const Text('Clear Filters'),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _FilteredLedgerBackSwipe extends StatefulWidget {
  const _FilteredLedgerBackSwipe({
    required this.enabled,
    required this.onCommitted,
    required this.child,
  });

  final bool enabled;
  final VoidCallback onCommitted;
  final Widget child;

  @override
  State<_FilteredLedgerBackSwipe> createState() =>
      _FilteredLedgerBackSwipeState();
}

class _FilteredLedgerBackSwipeState extends State<_FilteredLedgerBackSwipe> {
  static const _edgeWidth = 24.0;
  static const _commitDistance = 72.0;
  static const _quickCommitDistance = 36.0;
  static const _quickCommitDuration = Duration(milliseconds: 350);
  int? _pointer;
  Offset? _origin;
  Duration? _startedAt;
  var _eligible = false;
  var _disqualified = false;

  void _reset() {
    _pointer = null;
    _origin = null;
    _startedAt = null;
    _eligible = false;
    _disqualified = false;
  }

  @override
  Widget build(BuildContext context) {
    return Listener(
      key: const ValueKey('filtered-ledger-back-swipe'),
      behavior: HitTestBehavior.translucent,
      onPointerDown: widget.enabled
          ? (event) {
              if (_pointer != null || event.position.dx > _edgeWidth) return;
              _pointer = event.pointer;
              _origin = event.position;
              _startedAt = event.timeStamp;
              _eligible = true;
              _disqualified = false;
            }
          : null,
      onPointerMove: widget.enabled
          ? (event) {
              if (event.pointer != _pointer || !_eligible) return;
              final origin = _origin;
              if (origin == null) return;
              final delta = event.position - origin;
              if (delta.dx < -8 ||
                  (delta.dy.abs() > 18 &&
                      delta.dy.abs() > delta.dx.abs() * 0.8)) {
                _disqualified = true;
              }
            }
          : null,
      onPointerCancel: widget.enabled
          ? (event) {
              if (event.pointer == _pointer) _reset();
            }
          : null,
      onPointerUp: widget.enabled
          ? (event) {
              if (event.pointer != _pointer) return;
              final origin = _origin;
              final startedAt = _startedAt;
              final distance = origin == null
                  ? 0.0
                  : event.position.dx - origin.dx;
              final duration = startedAt == null
                  ? Duration.zero
                  : event.timeStamp - startedAt;
              final committed =
                  _eligible &&
                  !_disqualified &&
                  (distance >= _commitDistance ||
                      (distance >= _quickCommitDistance &&
                          duration <= _quickCommitDuration));
              _reset();
              if (committed) widget.onCommitted();
            }
          : null,
      child: widget.child,
    );
  }
}

