String ledgerMonthKey(DateTime month) => '${month.year}-${month.month}';

int compareTransactionsNewestFirst(TransactionRecord a, TransactionRecord b) {
  final dateOrder = b.date.compareTo(a.date);
  if (dateOrder != 0) return dateOrder;
  final createdOrder = b.sync.createdAt.compareTo(a.sync.createdAt);
  if (createdOrder != 0) return createdOrder;
  return b.id.compareTo(a.id);
}

String ledgerDayContext(DateTime date) {
  return switch (date.weekday) {
    DateTime.monday => 'Mon',
    DateTime.tuesday => 'Tue',
    DateTime.wednesday => 'Wed',
    DateTime.thursday => 'Thu',
    DateTime.friday => 'Fri',
    DateTime.saturday => 'Sat',
    DateTime.sunday => 'Sun',
    _ => '',
  };
}

DateTime ledgerCalendarDay(DateTime date) {
  final local = date.toLocal();
  return DateTime(local.year, local.month, local.day);
}

String ledgerFriendlyDayLabel(DateTime date, DateTime now) {
  final day = ledgerCalendarDay(date);
  final today = ledgerCalendarDay(now);
  if (day == today) return 'Today';
  if (day == today.subtract(const Duration(days: 1))) return 'Yesterday';
  const weekdays = [
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday',
    'Sunday',
  ];
  const months = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
  ];
  return '${weekdays[day.weekday - 1]}, ${months[day.month - 1]} ${day.day}';
}

String? ledgerTransactionTimeLabel(BuildContext context, DateTime date) {
  final local = date.toLocal();
  // Existing date-only records normalize to midnight. Do not invent a time
  // label for those transactions.
  if (local.hour == 0 &&
      local.minute == 0 &&
      local.second == 0 &&
      local.millisecond == 0 &&
      local.microsecond == 0) {
    return null;
  }
  return MaterialLocalizations.of(
    context,
  ).formatTimeOfDay(TimeOfDay.fromDateTime(local));
}

typedef _LedgerActivity = ({
  DateTime date,
  LedgerTransactionProjection? projection,
  GoalFundingEventRecord? fundingEvent,
  LedgerReservationActivityProjection? reservationActivity,
});

DateTime _ledgerActivityCreatedAt(_LedgerActivity activity) =>
    activity.projection?.transaction.sync.createdAt ??
    activity.fundingEvent?.sync.createdAt ??
    activity.reservationActivity!.createdAt;

DateTime _ledgerActivitySortTimestamp(_LedgerActivity activity) {
  if (activity.reservationActivity != null) {
    return activity.reservationActivity!.createdAt;
  }
  final date = activity.date;
  final carriesTime =
      date.hour != 0 ||
      date.minute != 0 ||
      date.second != 0 ||
      date.millisecond != 0 ||
      date.microsecond != 0;
  return carriesTime ? date : _ledgerActivityCreatedAt(activity);
}

String _ledgerActivityId(_LedgerActivity activity) =>
    activity.projection?.transaction.id ??
    activity.fundingEvent?.id ??
    activity.reservationActivity!.reservationOperationId;

class LedgerMonthSection extends StatelessWidget {
  const LedgerMonthSection({
    required this.month,
    required this.transactions,
    required this.goalFundingEvents,
    required this.reservationActivities,
    required this.store,
    required this.accountsById,
    required this.categoriesById,
    this.scopedAccountId,
    this.reservePendingIndicatorSpace = false,
    this.runningBalances,
    required this.isCollapsed,
    required this.onDismissFocus,
    required this.onToggle,
    super.key,
  });

  final DateTime month;
  final List<LedgerTransactionProjection> transactions;
  final List<GoalFundingEventRecord> goalFundingEvents;
  final List<LedgerReservationActivityProjection> reservationActivities;
  final FinanceDataStore store;
  final Map<String, v2_account.AccountRecord> accountsById;
  final Map<String, v2_category.CategoryRecord> categoriesById;
  final String? scopedAccountId;
  final bool reservePendingIndicatorSpace;
  final AccountRunningBalances? runningBalances;
  final bool isCollapsed;
  final VoidCallback onDismissFocus;
  final VoidCallback onToggle;

  @override
  Widget build(BuildContext context) {
    final income = transactions
        .where((item) => item.transaction.type == TransactionType.income)
        .fold(0, (total, item) => total + item.displayedAmountMinor.abs());
    final expenses = transactions
        .where((item) => item.transaction.type == TransactionType.expense)
        .fold(0, (total, item) => total + item.displayedAmountMinor.abs());
    final adjustments = transactions
        .where((item) => item.transaction.type == TransactionType.adjustment)
        .fold(0, (total, item) => total + item.displayedAmountMinor);
    final net = income - expenses + adjustments;
    final activities =
        <_LedgerActivity>[
          for (final projection in transactions)
            (
              date: projection.transaction.date,
              projection: projection,
              fundingEvent: null,
              reservationActivity: null,
            ),
          for (final fundingEvent in goalFundingEvents)
            (
              date: fundingEvent.date,
              projection: null,
              fundingEvent: fundingEvent,
              reservationActivity: null,
            ),
          for (final reservationActivity in reservationActivities)
            (
              date: reservationActivity.effectiveDate,
              projection: null,
              fundingEvent: null,
              reservationActivity: reservationActivity,
            ),
        ]..sort((left, right) {
          final dateOrder = ledgerCalendarDay(
            right.date,
          ).compareTo(ledgerCalendarDay(left.date));
          if (dateOrder != 0) return dateOrder;
          final leftTimestamp = _ledgerActivitySortTimestamp(left);
          final rightTimestamp = _ledgerActivitySortTimestamp(right);
          final createdOrder = rightTimestamp.compareTo(leftTimestamp);
          if (createdOrder != 0) return createdOrder;
          final leftId = _ledgerActivityId(left);
          final rightId = _ledgerActivityId(right);
          return rightId.compareTo(leftId);
        });
    final activitiesByDay = <DateTime, List<_LedgerActivity>>{};
    for (final activity in activities) {
      activitiesByDay
          .putIfAbsent(ledgerCalendarDay(activity.date), () => [])
          .add(activity);
    }
    final reduceMotion = MediaQuery.of(context).disableAnimations;

    return AppCard(
      padding: EdgeInsets.zero,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          InkWell(
            borderRadius: BorderRadius.circular(12),
            onTap: onToggle,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 13, 16, 13),
              child: Column(
                children: [
                  Row(
                    children: [
                      AnimatedRotation(
                        turns: isCollapsed ? -0.25 : 0,
                        duration: reduceMotion
                            ? Duration.zero
                            : Duration(milliseconds: 170),
                        curve: Curves.easeOutCubic,
                        child: Icon(AppIcon.dropdown, size: AppIconSize.form),
                      ),
                      const SizedBox(width: AppSpacing.xs),
                      Expanded(
                        child: Text(
                          monthLabel(month),
                          style: Theme.of(context).textTheme.titleMedium
                              ?.copyWith(fontWeight: FontWeight.w900),
                        ),
                      ),
                      Text(
                        '${activities.length} ${activities.length == 1 ? 'activity' : 'activities'}',
                        style: Theme.of(context).textTheme.labelMedium
                            ?.copyWith(
                              color: Theme.of(context)
                                  .colorScheme
                                  .onSurfaceVariant
                                  .withValues(alpha: 0.68),
                              fontSize: 11,
                              fontWeight: FontWeight.w600,
                            ),
                      ),
                    ],
                  ),
                  if (isCollapsed) ...[
                    const SizedBox(height: AppSpacing.xs),
                    LedgerMonthlyCompactSummary(
                      incomeMinor: income,
                      expensesMinor: expenses,
                      netMinor: net,
                      currency: store.preferences.currency,
                    ),
                  ],
                ],
              ),
            ),
          ),
          AnimatedSize(
            duration: reduceMotion
                ? Duration.zero
                : const Duration(milliseconds: 190),
            reverseDuration: reduceMotion
                ? Duration.zero
                : const Duration(milliseconds: 150),
            curve: Curves.easeOutCubic,
            alignment: Alignment.topCenter,
            child: isCollapsed
                ? const SizedBox.shrink()
                : Padding(
                    padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                    child: Column(
                      children: [
                        LedgerMonthlySummary(
                          incomeMinor: income,
                          expensesMinor: expenses,
                          netMinor: net,
                          currency: store.preferences.currency,
                        ),
                        const SizedBox(height: 14),
                        for (final entry in activitiesByDay.entries) ...[
                          _LedgerDayCard(
                            date: entry.key,
                            activities: entry.value,
                            store: store,
                            accountsById: accountsById,
                            categoriesById: categoriesById,
                            scopedAccountId: scopedAccountId,
                            reservePendingIndicatorSpace:
                                reservePendingIndicatorSpace,
                            runningBalances: runningBalances,
                            onDismissFocus: onDismissFocus,
                          ),
                          if (entry.key != activitiesByDay.entries.last.key)
                            const SizedBox(height: 14),
                        ],
                      ],
                    ),
                  ),
          ),
        ],
      ),
    );
  }
}

class _LedgerDayCard extends StatelessWidget {
  const _LedgerDayCard({
    required this.date,
    required this.activities,
    required this.store,
    required this.accountsById,
    required this.categoriesById,
    this.scopedAccountId,
    this.reservePendingIndicatorSpace = false,
    this.runningBalances,
    required this.onDismissFocus,
  });

  final DateTime date;
  final List<_LedgerActivity> activities;
  final FinanceDataStore store;
  final Map<String, v2_account.AccountRecord> accountsById;
  final Map<String, v2_category.CategoryRecord> categoriesById;
  final String? scopedAccountId;
  final bool reservePendingIndicatorSpace;
  final AccountRunningBalances? runningBalances;
  final VoidCallback onDismissFocus;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final borderRadius = BorderRadius.circular(19);
    final dayNet = activities.fold<int>(
      0,
      (total, activity) =>
          total +
          (activity.projection == null
              ? 0
              : ledgerActivitySummaryAmountMinor(activity.projection!)),
    );

    return Container(
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: borderRadius,
        border: Border.all(
          color: theme.colorScheme.outlineVariant.withValues(
            alpha: theme.brightness == Brightness.dark ? 0.38 : 0.46,
          ),
        ),
      ),
      child: ClipRRect(
        borderRadius: borderRadius,
        child: Column(
          children: [
            LedgerDaySectionHeader(
              date: date,
              netAmountMinor: dayNet,
              currency: store.preferences.currency,
            ),
            for (var index = 0; index < activities.length; index++) ...[
              if (activities[index].projection case final projection?)
                LedgerJournalRow(
                  projection: projection,
                  currency: store.preferences.currency,
                  showDateContext: false,
                  account: accountsById[projection.transaction.accountId],
                  category:
                      categoriesById[projection.categoryScope?.categoryId ??
                          projection.transaction.categoryId],
                  categoryName:
                      projection.categoryScope?.label ??
                      _ledgerTransactionCategoryNames(
                        projection.transaction,
                        categoriesById,
                      ),
                  metadataDetails: _ledgerMetadataDetails(
                    projection.transaction,
                    scopedAccountId: scopedAccountId,
                    accountsById: accountsById,
                    categoryName:
                        projection.categoryScope?.label ??
                        _ledgerTransactionCategoryNames(
                          projection.transaction,
                          categoriesById,
                        ),
                    reservationLabel: _transactionReservationMetadataLabel(
                      projection.transaction,
                      goals: store.goals,
                      funds: store.funds,
                    ),
                  ),
                  isAccountScoped: scopedAccountId != null,
                  reservePendingIndicatorSpace: reservePendingIndicatorSpace,
                  runningBalanceMinor: runningBalances
                      ?.afterTransaction[projection.transaction.id],
                  runningBalanceAccount: scopedAccountId == null
                      ? null
                      : accountsById[scopedAccountId],
                  showIcon: store.preferences.showLedgerIcons,
                  showTimestamp: store.preferences.showLedgerTimestamps,
                  showSplitIndicator:
                      store.preferences.showLedgerSplitIndicator,
                  onTap: () async {
                    onDismissFocus();
                    await showTransactionDetails(
                      context,
                      projection.transaction.id,
                      projection: projection.isCategoryProjected
                          ? projection
                          : null,
                    );
                    if (context.mounted) onDismissFocus();
                  },
                  onLongPress: () async {
                    onDismissFocus();
                    AppHaptics.longPressAction();
                    await showTransactionOptions(
                      context,
                      projection.transaction.id,
                    );
                    if (context.mounted) onDismissFocus();
                  },
                )
              else if (activities[index].reservationActivity
                  case final reservationActivity?)
                ReservationLedgerRow(
                  activity: reservationActivity,
                  showDateContext: false,
                  account: accountsById[reservationActivity.fundingAccountId],
                  isAccountScoped: scopedAccountId != null,
                  currency: store.preferences.currency,
                  showIcon: store.preferences.showLedgerIcons,
                  showTimestamp: store.preferences.showLedgerTimestamps,
                  showSplitIndicator:
                      store.preferences.showLedgerSplitIndicator,
                  reservePendingIndicatorSpace: reservePendingIndicatorSpace,
                  onTap: () => showReservationActivityDetails(
                    context,
                    reservationActivity,
                    account: accountsById[reservationActivity.fundingAccountId],
                    currency: store.preferences.currency,
                  ),
                )
              else
                GoalFundingLedgerRow(
                  event: activities[index].fundingEvent!,
                  showDateContext: false,
                  account:
                      accountsById[activities[index]
                          .fundingEvent!
                          .sourceAccountId],
                  isAccountScoped: scopedAccountId != null,
                  reservePendingIndicatorSpace: reservePendingIndicatorSpace,
                  currency: store.preferences.currency,
                  runningBalanceMinor:
                      runningBalances?.afterGoalFundingEvent[activities[index]
                          .fundingEvent!
                          .id],
                  showIcon: store.preferences.showLedgerIcons,
                  showTimestamp: store.preferences.showLedgerTimestamps,
                  showSplitIndicator:
                      store.preferences.showLedgerSplitIndicator,
                  onTap: () => showGoalFundingDetails(
                    context,
                    activities[index].fundingEvent!.id,
                  ),
                ),
              if (index != activities.length - 1)
                Divider(
                  height: 1,
                  indent: 58,
                  endIndent: 16,
                  color: theme.colorScheme.outlineVariant.withValues(
                    alpha: 0.135,
                  ),
                ),
            ],
          ],
        ),
      ),
    );
  }
}

