class LedgerJournalRow extends StatelessWidget {
  const LedgerJournalRow({
    required this.projection,
    required this.currency,
    required this.onTap,
    required this.onLongPress,
    this.account,
    this.category,
    this.categoryName,
    this.metadataDetails,
    this.runningBalanceMinor,
    this.runningBalanceAccount,
    this.isAccountScoped = false,
    this.reservePendingIndicatorSpace = false,
    this.showDateContext = true,
    this.showIcon = true,
    this.showTimestamp = true,
    this.showSplitIndicator = true,
    super.key,
  });

  final LedgerTransactionProjection projection;
  TransactionRecord get transaction => projection.transaction;
  final CurrencyFormatSettings currency;
  final v2_account.AccountRecord? account;
  final v2_category.CategoryRecord? category;
  final String? categoryName;
  final String? metadataDetails;
  final int? runningBalanceMinor;
  final v2_account.AccountRecord? runningBalanceAccount;
  final bool isAccountScoped;
  final bool reservePendingIndicatorSpace;
  final bool showDateContext;
  final bool showIcon;
  final bool showTimestamp;
  final bool showSplitIndicator;
  final VoidCallback onTap;
  final VoidCallback onLongPress;

  @override
  Widget build(BuildContext context) {
    final signedAmount = projection.displayedAmountMinor;
    final timeLabel = ledgerTransactionTimeLabel(context, transaction.date);
    final resolvedMetadataDetails =
        metadataDetails ??
        [
          if (account != null) account!.name,
          if (categoryName != null) categoryName,
          if (transaction.type == TransactionType.adjustment)
            'Manual balance adjustment',
          if (transaction.isTransfer) 'Transfer',
        ].join(' • ');
    final hasSplit = projection.isPartOfSplit || transaction.isSplit;
    final secondaryStyle =
        Theme.of(context).textTheme.bodySmall?.copyWith(
          color: Theme.of(context).colorScheme.onSurfaceVariant,
        ) ??
        const TextStyle(fontSize: 12);
    return Dismissible(
      key: ValueKey('ledger-swipe-${transaction.id}'),
      dismissThresholds: const {
        DismissDirection.startToEnd: 0.28,
        DismissDirection.endToStart: 0.28,
      },
      confirmDismiss: (direction) async {
        if (direction == DismissDirection.endToStart &&
            transaction.status == v2_transaction.TransactionStatus.pending) {
          await updateTransactionStatus(
            context,
            transaction.id,
            v2_transaction.TransactionStatus.cleared,
          );
          return false;
        }
        AppHaptics.toggleSelection();
        await showTransactionOptions(
          context,
          transaction.id,
          allowedActions: direction == DismissDirection.endToStart
              ? const {'edit', 'delete'}
              : const {'duplicate', 'split', 'schedule'},
        );
        return false;
      },
      background: SwipeActionBackground(
        alignment: Alignment.centerLeft,
        icon: AppIcon.copy,
        label: 'More',
      ),
      secondaryBackground: SwipeActionBackground(
        alignment: Alignment.centerRight,
        icon: transaction.status == v2_transaction.TransactionStatus.pending
            ? AppIcon.checkRounded
            : AppIcon.edit,
        label: transaction.status == v2_transaction.TransactionStatus.pending
            ? 'Mark Cleared'
            : 'Actions',
      ),
      child: InkWell(
        onTap: onTap,
        onLongPress: onLongPress,
        child: SizedBox(
          height: 72,
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                if (showDateContext) ...[
                  SizedBox(
                    width: 38,
                    child: Text(
                      '${transaction.date.day}\n${ledgerDayContext(transaction.date)}',
                      textAlign: TextAlign.center,
                      style: Theme.of(context).textTheme.labelMedium?.copyWith(
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                        fontWeight: FontWeight.w800,
                        height: 1.1,
                      ),
                    ),
                  ),
                  const SizedBox(width: AppSpacing.sm),
                ],
                if (showIcon) ...[
                  KeyedSubtree(
                    key: ValueKey('ledger-icon-${transaction.id}'),
                    child: category != null
                        ? CategoryIconBadge.category(
                            category!,
                            size: CategoryIconBadgeSize.row,
                          )
                        : _LedgerIconBadge(
                            icon: account == null
                                ? AppIcon.receipt
                                : v2AccountIcon(account!.type),
                            semanticLabel: account == null
                                ? 'Transaction'
                                : '${account!.name} account',
                          ),
                  ),
                  const SizedBox(width: AppSpacing.sm),
                ],
                Expanded(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Expanded(
                            child: Text(
                              transaction.payee,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: Theme.of(context).textTheme.bodyLarge
                                  ?.copyWith(
                                    fontSize: 17,
                                    fontWeight: FontWeight.w700,
                                    letterSpacing: -0.15,
                                  ),
                            ),
                          ),
                          const SizedBox(width: AppSpacing.sm),
                          SizedBox(
                            width: 104,
                            child: Align(
                              alignment: Alignment.centerRight,
                              child: MoneyText(
                                amountMinor: signedAmount,
                                currency: currency,
                                fontSize: 16,
                                fontWeight: FontWeight.w800,
                                showPositiveSign:
                                    transaction.type == TransactionType.income,
                                color: signedAmount < 0
                                    ? AppColors.danger
                                    : null,
                              ),
                            ),
                          ),
                        ],
                      ),
                      if (resolvedMetadataDetails.isNotEmpty) ...[
                        const SizedBox(height: 3),
                        _LedgerSecondaryLine(
                          rowId: transaction.id,
                          details: resolvedMetadataDetails,
                          timeLabel: showTimestamp ? timeLabel : null,
                          showTimestamp: showTimestamp,
                          showPending:
                              transaction.status ==
                              v2_transaction.TransactionStatus.pending,
                          reservePendingSpace: reservePendingIndicatorSpace,
                          showSplit: showSplitIndicator && hasSplit,
                          reserveSplitSpace: showSplitIndicator,
                          isAccountScoped: isAccountScoped,
                          style: secondaryStyle,
                          trailing: runningBalanceMinor == null
                              ? null
                              : runningBalanceAccount == null
                              ? MoneyText(
                                  key: ValueKey(
                                    'ledger-running-balance-${transaction.id}',
                                  ),
                                  amountMinor: runningBalanceMinor!,
                                  currency: currency,
                                  fontSize: 11,
                                  fontWeight: FontWeight.w500,
                                  color: Theme.of(
                                    context,
                                  ).colorScheme.onSurfaceVariant,
                                )
                              : FittedBox(
                                  fit: BoxFit.scaleDown,
                                  alignment: Alignment.centerRight,
                                  child: AccountBalanceText(
                                    key: ValueKey(
                                      'ledger-running-balance-${transaction.id}',
                                    ),
                                    accountType: runningBalanceAccount!.type,
                                    signedBalanceMinor: runningBalanceMinor!,
                                    currency: currency,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w500,
                                    compactCreditLabel: true,
                                    neutralColor: Theme.of(
                                      context,
                                    ).colorScheme.onSurfaceVariant,
                                  ),
                                ),
                        ),
                      ],
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

String? _ledgerTransactionCategoryNames(
  TransactionRecord transaction,
  Map<String, v2_category.CategoryRecord> categoriesById,
) {
  final categoryNames = <String>[];
  for (final allocation in transaction.effectiveCategoryAllocations) {
    final name = categoriesById[allocation.categoryId]?.name;
    if (name != null && name.isNotEmpty && !categoryNames.contains(name)) {
      categoryNames.add(name);
    }
  }
  if (categoryNames.isNotEmpty) return categoryNames.join(' • ');
  final categoryId = transaction.categoryId;
  return categoryId == null ? null : categoriesById[categoryId]?.name;
}

String _ledgerMetadataDetails(
  TransactionRecord transaction, {
  required String? scopedAccountId,
  required Map<String, v2_account.AccountRecord> accountsById,
  required String? categoryName,
  String? reservationLabel,
}) {
  final transferDestinationName = transaction.isTransfer
      ? accountsById[transaction.transferAccountId]?.name
      : null;
  if (scopedAccountId == null) {
    return [
      accountsById[transaction.accountId]?.name,
      categoryName,
      reservationLabel,
      if (transaction.type == TransactionType.adjustment)
        'Manual balance adjustment',
      if (transaction.isTransfer)
        transferDestinationName == null || transferDestinationName.isEmpty
            ? 'Transfer'
            : 'To $transferDestinationName',
    ].whereType<String>().where((value) => value.isNotEmpty).join(' • ');
  }
  if (transaction.isTransfer) {
    final isOutgoing = transaction.accountId == scopedAccountId;
    final otherAccountId = isOutgoing
        ? transaction.transferAccountId
        : transaction.accountId;
    final otherAccountName = accountsById[otherAccountId]?.name;
    return [
      otherAccountName == null || otherAccountName.isEmpty
          ? 'Transfer'
          : '${isOutgoing ? 'To' : 'From'} $otherAccountName',
      reservationLabel,
    ].whereType<String>().where((value) => value.isNotEmpty).join(' • ');
  }
  if (transaction.type == TransactionType.adjustment) {
    return [
      categoryName?.isNotEmpty == true
          ? categoryName!
          : 'Manual balance adjustment',
      reservationLabel,
    ].whereType<String>().where((value) => value.isNotEmpty).join(' • ');
  }
  return [
    categoryName?.isNotEmpty == true
        ? categoryName!
        : transactionTypeLabel(transaction.type),
    reservationLabel,
  ].whereType<String>().where((value) => value.isNotEmpty).join(' • ');
}

String? _transactionReservationMetadataLabel(
  TransactionRecord transaction, {
  required Iterable<GoalRecord> goals,
  required Iterable<FundRecord> funds,
}) {
  final containerId = transaction.reservationContainerId;
  if (containerId == null || containerId.isEmpty) return null;
  return switch (transaction.reservationContainerType) {
    ReservationContainerType.goal =>
      '${goals.where((goal) => goal.id == containerId).firstOrNull?.name ?? 'Deleted'} Goal',
    ReservationContainerType.fund =>
      '${funds.where((fund) => fund.id == containerId).firstOrNull?.name ?? 'Deleted'} Fund',
    null => null,
  };
}

/// All Ledger activity types use the same trailing columns. A reservation
/// movement leaves the Split/Pending cells empty, but does not move the clock.
class _LedgerSecondaryLine extends StatelessWidget {
  const _LedgerSecondaryLine({
    required this.rowId,
    required this.details,
    required this.timeLabel,
    required this.style,
    required this.isAccountScoped,
    required this.showTimestamp,
    required this.reserveSplitSpace,
    required this.reservePendingSpace,
    this.showSplit = false,
    this.showPending = false,
    this.trailing,
  });

  final String rowId;
  final String details;
  final String? timeLabel;
  final TextStyle style;
  final bool isAccountScoped;
  final bool showTimestamp;
  final bool reserveSplitSpace;
  final bool reservePendingSpace;
  final bool showSplit;
  final bool showPending;
  final Widget? trailing;

  @override
  Widget build(BuildContext context) {
    final mediaSize = MediaQuery.sizeOf(context);
    final isCompact = mediaSize.width < 600;
    final platform = Theme.of(context).platform;
    final usesWideMetadataInset =
        (platform == TargetPlatform.iOS && mediaSize.shortestSide >= 600) ||
        (platform == TargetPlatform.macOS && !isCompact);
    final amountSlotWidth = usesWideMetadataInset
        ? (isAccountScoped ? 220.0 : 230.0)
        : isAccountScoped
        ? (isCompact ? 80.0 : 96.0)
        : (isCompact ? 44.0 : 56.0);

    return Row(
      children: [
        Expanded(
          child: _LedgerMetadataLine(
            rowId: rowId,
            details: details,
            timeLabel: timeLabel,
            reserveTimestampSpace: showTimestamp,
            reserveSplitSpace: reserveSplitSpace,
            reservePendingSpace: reservePendingSpace,
            showSplit: showSplit,
            showPending: showPending,
            style: style,
          ),
        ),
        const SizedBox(width: AppSpacing.sm),
        SizedBox(
          key: ValueKey('ledger-secondary-amount-slot-$rowId'),
          width: amountSlotWidth,
          height: 18,
          child: trailing == null
              ? null
              : Align(alignment: Alignment.centerRight, child: trailing),
        ),
      ],
    );
  }
}

class _LedgerMetadataLine extends StatelessWidget {
  const _LedgerMetadataLine({
    required this.rowId,
    required this.details,
    required this.timeLabel,
    required this.style,
    this.showSplit = false,
    this.showPending = false,
    this.reserveTimestampSpace = true,
    this.reserveSplitSpace = true,
    this.reservePendingSpace = false,
  });

  final String rowId;
  final String details;
  final String? timeLabel;
  final TextStyle style;
  final bool showSplit;
  final bool showPending;
  final bool reserveTimestampSpace;
  final bool reserveSplitSpace;
  final bool reservePendingSpace;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        const splitWidth = 41.0;
        const pendingWidth = 16.0;
        const metadataGap = 6.0;
        const indicatorGap = 5.0;
        final hasPendingSlot = reservePendingSpace || showPending;
        final hasTrailingIndicator = reserveSplitSpace || hasPendingSlot;
        final preferredTimestampWidth = _ledgerTimestampSlotWidth(
          context,
          timeLabel,
          style,
        );
        final timestampWidth = reserveTimestampSpace
            ? min(
                preferredTimestampWidth,
                max(
                  0.0,
                  constraints.maxWidth -
                      (reserveSplitSpace ? splitWidth : 0) -
                      (hasPendingSlot ? pendingWidth : 0) -
                      metadataGap -
                      (hasPendingSlot ? indicatorGap : 0) -
                      (reserveSplitSpace ? indicatorGap : 0),
                ),
              )
            : 0.0;
        return Row(
          children: [
            Expanded(
              child: Text(
                key: ValueKey('ledger-metadata-details-$rowId'),
                details,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                textAlign: TextAlign.left,
                style: style,
              ),
            ),
            if (hasTrailingIndicator || reserveTimestampSpace)
              const SizedBox(width: metadataGap),
            if (hasPendingSlot) ...[
              SizedBox(
                key: ValueKey('ledger-pending-slot-$rowId'),
                width: pendingWidth,
                child: showPending
                    ? KeyedSubtree(
                        key: ValueKey('ledger-pending-indicator-$rowId'),
                        child: const _LedgerPendingIndicator(),
                      )
                    : null,
              ),
              const SizedBox(width: indicatorGap),
            ],
            if (reserveTimestampSpace)
              SizedBox(
                key: ValueKey('ledger-timestamp-slot-$rowId'),
                width: timestampWidth,
                child: Text(
                  timeLabel ?? '',
                  maxLines: 1,
                  softWrap: false,
                  overflow: TextOverflow.clip,
                  textAlign: TextAlign.right,
                  style: style,
                ),
              ),
            if (reserveSplitSpace) ...[
              const SizedBox(width: indicatorGap),
              SizedBox(
                key: ValueKey('ledger-split-slot-$rowId'),
                width: splitWidth,
                child: showSplit
                    ? Center(
                        child: KeyedSubtree(
                          key: ValueKey('ledger-split-indicator-$rowId'),
                          child: const _LedgerSplitCapsule(),
                        ),
                      )
                    : null,
              ),
            ],
          ],
        );
      },
    );
  }
}

double _ledgerTimestampSlotWidth(
  BuildContext context,
  String? label,
  TextStyle style,
) {
  if (label == null || label.isEmpty) return 0;
  final textDirection = Directionality.of(context);
  final textScaler = MediaQuery.textScalerOf(context);
  final painter = TextPainter(
    text: TextSpan(text: label, style: style),
    maxLines: 1,
    textDirection: textDirection,
    textScaler: textScaler,
  )..layout();
  // One logical point on either side protects glyph bearings without keeping
  // unused leading space from the old fixed-width reservation. Timestamp
  // right edges remain fixed by the trailing indicator slot.
  return painter.width.ceilToDouble() + 2;
}

