                tooltip: isCollapsed ? 'Expand calendar' : 'Collapse calendar',
                onPressed: () {
                  AppHaptics.selection();
                  onToggleCollapsed();
                },
                icon: AnimatedRotation(
                  turns: isCollapsed ? 0 : 0.5,
