  const ScheduledMonthlySummaryValue({
    required this.label,
    required this.value,
    required this.valueKey,
    this.labelKey,
    super.key,
  });

  final String label;
  final String value;
  final Key valueKey;
  final Key? labelKey;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Expanded(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            label,
            key: labelKey,
            style: theme.textTheme.labelSmall?.copyWith(
              color: AppTheme.muted,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 2),
          Text(
            value,
            key: valueKey,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: theme.textTheme.bodySmall?.copyWith(
              fontWeight: FontWeight.w900,
            ),
          ),
        ],
      ),
    );
  }
}

class CategoriesView extends StatefulWidget {
  const CategoriesView({super.key});

  @override
  State<CategoriesView> createState() => _CategoriesViewState();
}

class _CategoriesViewState extends State<CategoriesView> {
  final Set<String> _collapsedCategoryIds = <String>{};
  var _initializedExpansionState = false;

  @override
  Widget build(BuildContext context) {
    final store = FinanceDataStoreScope.watch(context);
    final categories = store.categories
        .where((category) => category.isVisible)
        .toList(growable: false);
    if (!_initializedExpansionState) {
      final parentIds = categories
          .map((category) => category.parentCategoryId)
          .whereType<String>()
          .toSet();
      _collapsedCategoryIds.addAll(parentIds);
      _initializedExpansionState = true;
    }
    final managementIndex = ManagementLedgerIndex.build(
      transactions: store.transactions,
      accounts: store.accounts,
      categories: store.categories,
      now: DateTime.now(),
    );
    final displayCategories = visibleCategoriesInDisplayOrder(
      categories,
      _collapsedCategoryIds,
    );
    final categoriesById = {
      for (final category in categories) category.id: category,
    };
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Align(
          alignment: Alignment.centerRight,
          child: FilledButton.icon(
            onPressed: () => showCategoryDialog(context),
            icon: Icon(AppIcon.add),
            label: const Text('Add category'),
          ),
        ),
        const SizedBox(height: 12),
        AppCard(
          padding: const EdgeInsets.symmetric(vertical: 4),
          child: AnimatedSize(
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOutCubic,
            alignment: Alignment.topCenter,
            child: Column(
              children: [
                for (
                  var index = 0;
                  index < displayCategories.length;
                  index++
                ) ...[
                  Builder(
                    builder: (context) {
                      final category = displayCategories[index];
                      final depth = categoryDepth(category, categoriesById);
                      final childCount = categories
                          .where(
                            (candidate) =>
                                candidate.parentCategoryId == category.id,
                          )
                          .length;
                      final hasChildren = childCount > 0;
                      final isChild = depth > 0;
                      final isExpanded = !_collapsedCategoryIds.contains(
                        category.id,
                      );
                      final subtitle = categorySubtitle(
                        category,
                        categoriesById,
                      );
                      return Padding(
                        padding: EdgeInsets.only(left: depth * 22.0),
                        child: Stack(
                          children: [
                            if (isChild) ...[
                              Positioned(
                                left: 5,
                                top: 0,
                                bottom: 0,
                                child: Container(
                                  key: ValueKey(
                                    'category-branch-${category.id}',
                                  ),
                                  width: 1,
                                  color: AppTheme.line.withValues(alpha: 0.7),
                                ),
                              ),
                              Positioned(
                                left: 5,
                                top: 31,
                                child: Container(
                                  width: 10,
                                  height: 1,
                                  color: AppTheme.line.withValues(alpha: 0.7),
                                ),
                              ),
                            ],
                            Padding(
                              padding: EdgeInsets.only(left: isChild ? 10 : 0),
                              child: ManagementSwipeRow(
                                key: ValueKey('category-swipe-${category.id}'),
                                actions: [
                                  ManagementSwipeAction(
                                    label: 'Edit',
                                    icon: AppIcon.edit,
                                    color: AppTheme.accent,
                                    actionKey: ValueKey(
                                      'category-edit-${category.id}',
                                    ),
                                    onPressed: () => showCategoryDialog(
                                      context,
                                      categoryId: category.id,
                                    ),
                                  ),
                                  ManagementSwipeAction(
                                    label: 'Archive',
                                    icon: AppIcon.archive,
                                    color: Theme.of(
                                      context,
                                    ).colorScheme.onSurfaceVariant,
                                    actionKey: ValueKey(
                                      'category-archive-${category.id}',
                                    ),
                                    onPressed: () =>
                                        store.archiveCategory(category.id),
                                  ),
                                  ManagementSwipeAction(
                                    label: 'Delete',
                                    icon: AppIcon.delete,
                                    color: AppColors.danger,
                                    actionKey: ValueKey(
                                      'category-delete-${category.id}',
                                    ),
                                    onPressed: () =>
                                        store.deleteCategory(category.id),
                                  ),
                                ],
                                child: ListTile(
                                  key: ValueKey('category-row-${category.id}'),
                                  dense: true,
                                  visualDensity: const VisualDensity(
                                    vertical: -1,
                                  ),
                                  contentPadding: const EdgeInsets.symmetric(
                                    horizontal: 14,
                                    vertical: 2,
                                  ),
                                  onTap: () => showCategoryDetails(
                                    context,
                                    category.id,
                                    index: managementIndex,
                                  ),
                                  onLongPress: () {
                                    AppHaptics.longPressAction();
                                    showCategoryActions(context, category);
                                  },
                                  leading: CategoryIconBadge.category(
                                    category,
                                    size: isChild
                                        ? CategoryIconBadgeSize.compact
                                        : CategoryIconBadgeSize.row,
                                  ),
                                  title: Text(
                                    category.name,
                                    style: isChild
                                        ? Theme.of(
                                            context,
                                          ).textTheme.bodyMedium?.copyWith(
                                            color: Theme.of(
                                              context,
                                            ).colorScheme.onSurfaceVariant,
                                            fontWeight: FontWeight.w600,
                                          )
                                        : const TextStyle(
                                            fontWeight: FontWeight.w700,
                                          ),
                                  ),
                                  subtitle: Text(
                                    hasChildren && !isExpanded
                                        ? '$subtitle · $childCount ${childCount == 1 ? 'subcategory' : 'subcategories'}'
                                        : subtitle,
                                    style: Theme.of(context).textTheme.bodySmall
                                        ?.copyWith(
                                          color: Theme.of(
                                            context,
                                          ).colorScheme.onSurfaceVariant,
                                          fontSize: isChild ? 11 : null,
                                        ),
                                  ),
                                  trailing: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      ManagementCountPill(
                                        key: ValueKey(
                                          'category-count-${category.id}',
                                        ),
                                        count: managementIndex.categoryCount(
                                          category.id,
                                        ),
                                        semanticLabel:
                                            '${category.name}, ${managementIndex.categoryCount(category.id)} transactions in the last 12 months',
                                        onTap: () => openManagementLedger(
                                          context,
                                          ManagementLedgerFilter.category(
                                            categoryId: category.id,
                                            label: category.name,
                                          ),
                                        ),
                                      ),
                                      const SizedBox(width: 6),
                                      if (hasChildren)
                                        IconButton(
                                          tooltip: isExpanded
                                              ? 'Collapse ${category.name}'
                                              : 'Expand ${category.name}',
                                          onPressed: () {
                                            AppHaptics.selection();
                                            setState(() {
                                              if (isExpanded) {
                                                _collapsedCategoryIds.add(
                                                  category.id,
                                                );
                                              } else {
                                                _collapsedCategoryIds.remove(
                                                  category.id,
                                                );
                                              }
                                            });
                                          },
                                          icon: AnimatedRotation(
                                            turns: isExpanded ? 0.25 : 0,
                                            duration: const Duration(
                                              milliseconds: 180,
                                            ),
                                            curve: Curves.easeOutCubic,
                                            child: Icon(AppIcon.chevronRight),
                                          ),
                                        )
                                      else
                                        const SizedBox(width: 48),
                                    ],
                                  ),
                                ),
                              ),
                            ),
                          ],
                        ),
                      );
                    },
                  ),
                  if (index < displayCategories.length - 1)
                    Divider(
                      height: 1,
                      color: Theme.of(
                        context,
                      ).colorScheme.outlineVariant.withValues(alpha: 0.52),
                      indent:
                          58 +
                          categoryDepth(
                                displayCategories[index],
                                categoriesById,
                              ) *
                              18.0,
                    ),
                ],
              ],
            ),
          ),
        ),
      ],
    );
  }
}

class SettingsView extends StatefulWidget {
  const SettingsView({
    this.dataManagementOnly = false,
    this.onSelectSection,
    this.syncLabel = 'Synced',
    this.syncErrorLabel,
    this.syncDiagnosticLabel,
    this.lastSuccessfulSyncLabel,
    this.onSyncNow,
    this.onSignOut,
    this.onDeleteAccount,
    this.exportFileService,
    this.backupImportFileService,
    this.backupSafetyFileService,
    this.iCloudBackupStorage,
    this.backupRestoreValidator = const BackupRestoreValidator(),
    this.now,
    super.key,
  });

  final bool dataManagementOnly;
  final ValueChanged<FinanceSection>? onSelectSection;
  final String syncLabel;
  final String? syncErrorLabel;
  final String? syncDiagnosticLabel;
  final String? lastSuccessfulSyncLabel;
  final Future<void> Function()? onSyncNow;
  final VoidCallback? onSignOut;
  final Future<void> Function()? onDeleteAccount;
  final ExportFileService? exportFileService;
  final BackupImportFileService? backupImportFileService;
  final BackupSafetyFileService? backupSafetyFileService;
  final BackupStorage? iCloudBackupStorage;
  final BackupRestoreValidator backupRestoreValidator;
  final DateTime Function()? now;

  static const _currencyOptions = [
    CurrencyFormatSettings(currencyCode: 'USD', symbol: r'$'),
    CurrencyFormatSettings(currencyCode: 'PHP', symbol: 'PHP '),
    CurrencyFormatSettings(currencyCode: 'EUR', symbol: 'EUR '),
    CurrencyFormatSettings(currencyCode: 'GBP', symbol: 'GBP '),
    CurrencyFormatSettings(currencyCode: 'CAD', symbol: r'C$'),
    CurrencyFormatSettings(currencyCode: 'AUD', symbol: r'A$'),
    CurrencyFormatSettings(currencyCode: 'JPY', symbol: 'JPY '),
  ];

  @override
  State<SettingsView> createState() => _SettingsViewState();

  static CurrencyFormatSettings _currencyFor(String code) {
    return _currencyOptions.firstWhere(
      (option) => option.currencyCode == code,
      orElse: () => _currencyOptions.first,
    );
  }
}

class _SettingsViewState extends State<SettingsView> {
  ExportFileService? _defaultExportFileService;
  BackupImportFileService? _defaultBackupImportFileService;
  BackupSafetyFileService? _defaultBackupSafetyFileService;
  _ExportKind? _sharingExport;
  var _isImportingBackup = false;
  var _isResettingData = false;
  var _isDeletingAccount = false;
  AutomaticBackupStatus? _automaticBackupStatus;
  ICloudBackupStorage? _defaultICloudBackupStorage;

  @override
  void initState() {
    super.initState();
    _loadAutomaticBackupStatus();
  }

  Future<void> _loadAutomaticBackupStatus() async {
    final status = await AutomaticBackupService(
      iCloudStorage: _iCloudBackupStorage,
    ).loadStatus();
    if (mounted) setState(() => _automaticBackupStatus = status);
  }

  BackupStorage get _iCloudBackupStorage =>
      widget.iCloudBackupStorage ??
      (_defaultICloudBackupStorage ??= ICloudBackupStorage());

  ExportFileService get _exportFileService =>
      widget.exportFileService ??
      (_defaultExportFileService ??= ExportFileService());

  BackupImportFileService get _backupImportFileService =>
      widget.backupImportFileService ??
      (_defaultBackupImportFileService ??= BackupImportFileService());

  BackupSafetyFileService get _backupSafetyFileService =>
      widget.backupSafetyFileService ??
      (_defaultBackupSafetyFileService ??= BackupSafetyFileService());

  @override
  Widget build(BuildContext context) {
    final store = FinanceDataStoreScope.watch(context);
    final preferences = store.preferences;
    final isSyncing = widget.syncLabel == 'Syncing';

    if (widget.dataManagementOnly) {
      return _buildDataManagementContent(store, preferences);
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        SettingsSectionCard(
          title: 'Cloud Sync',
          children: [
            SettingsActionRow(
              icon: widget.syncLabel == 'Sync issue'
                  ? AppIcon.cloudOff
                  : AppIcon.cloudDone,
              title: 'Status',
              subtitle: switch (widget.syncLabel) {
                'Synced' => 'Your data is securely synced',
                'Syncing' => 'Your data is syncing',
                'Sync issue' =>
                  widget.syncErrorLabel ?? 'Cloud sync needs attention',
                'Offline' => 'You are currently offline',
                _ => 'Your data is stored securely',
              },
              trailingText: widget.syncLabel,
              showStatusPill: true,
              onTap: widget.onSyncNow == null || isSyncing
                  ? null
                  : () => widget.onSyncNow!.call(),
            ),
            SettingsActionRow(
              icon: AppIcon.schedule,
              title: 'Last successful sync',
              subtitle:
                  widget.lastSuccessfulSyncLabel ??
                  (widget.syncLabel == 'Synced'
                      ? 'This session'
                      : 'Not available'),
              showDivider: widget.onSyncNow != null || widget.onSignOut != null,
            ),
            if (widget.onSyncNow != null)
              SettingsActionRow(
                icon: AppIcon.reports,
