  Future<void> _confirmAndDeleteAccount() async {
    final deleteAccount = widget.onDeleteAccount;
    if (deleteAccount == null || _isDeletingAccount) return;
    final confirmed = await _showDeleteTrackmarkAccountConfirmation(context);
    if (!mounted || !confirmed) return;

    setState(() => _isDeletingAccount = true);
    try {
      await deleteAccount();
    } on AuthException catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(SnackBar(content: Text(error.message)));
    } on Object {
      if (!mounted) return;
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(
          const SnackBar(
            content: Text(
              'Trackmark could not delete the account. Nothing was deleted.',
            ),
          ),
        );
    } finally {
      if (mounted) setState(() => _isDeletingAccount = false);
    }
  }

  Widget _buildDataManagementContent(
    FinanceDataStore store,
    UserPreferences preferences,
  ) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        SettingsSectionCard(
          title: 'Data Management',
          children: [
            SettingsActionRow(
              key: const ValueKey('reset-preferences-row'),
              icon: AppIcon.restore,
              title: 'Reset Preferences',
              subtitle:
                  'Restore app settings and replay the introduction on next launch. Financial data stays unchanged.',
              onTap: _confirmResetPreferences,
            ),
