  Future<void> _confirmResetPreferences() async {
    final store = FinanceDataStoreScope.read(context);
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => TransactionSheetFrame(
        title: 'Reset Preferences?',
        actions: TransactionFormActions(
          saveLabel: 'Reset Preferences',
          saveKey: const ValueKey('confirm-reset-preferences'),
          onCancel: () => Navigator.pop(dialogContext, false),
          onSave: () => Navigator.pop(dialogContext, true),
        ),
        child: const Padding(
          padding: EdgeInsets.symmetric(vertical: AppSpacing.md),
          child: Text(
            'Restore app settings to their defaults, including notification and automatic sync/backup preferences. The introduction will appear on your next launch.\n\nYour accounts, transactions, Plans, payees, sign-in, and existing backups will not be deleted.',
          ),
        ),
      ),
    );
    if (!mounted || confirmed != true) return;
    try {
      await resetTrackmarkPreferences(store);
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Preferences reset. The introduction will appear on your next launch.',
          ),
        ),
      );
    } on Object {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Preferences could not be fully reset. Please try again.',
          ),
        ),
      );
    }
  }

  String _backupStatusDateLabel(DateTime value) {
    final local = value.toLocal();
    return '${shortDate(local)} · ${TimeOfDay.fromDateTime(local).format(context)}';
  }

  String _automaticBackupLocationLabel(AutomaticBackupLocation value) =>
      switch (value) {
        AutomaticBackupLocation.local => 'On My Device',
        AutomaticBackupLocation.iCloud => 'iCloud Drive',
      };

  String _automaticBackupStatusLabel() {
    final status = _automaticBackupStatus;
    if (status == null) return 'Never';
    final at = status.lastResultAt ?? status.lastSuccessfulAt;
    final resultLabel = switch (status.lastResult) {
      AutomaticBackupResult.savedOnDevice => 'Saved on this device',
      AutomaticBackupResult.uploadedToICloud => 'Uploaded to iCloud',
      AutomaticBackupResult.waitingForICloud => 'Waiting for iCloud',
      AutomaticBackupResult.iCloudUnavailableSavedOnDevice =>
        'iCloud unavailable — saved on this device',
      AutomaticBackupResult.backupFailed => 'Backup failed',
      null => status.lastFailureAt == null ? null : 'Backup needs attention',
    };
    if (at == null) return resultLabel ?? 'Never';
    final date = _backupStatusDateLabel(at);
    return resultLabel == null ? date : '$date\n$resultLabel';
  }

  Future<void> _pickAutomaticBackupLocation(FinanceDataStore store) async {
    final current = store.preferences.automaticBackupLocation;
    final selected = await showPolishedChoicePicker<AutomaticBackupLocation>(
      context,
      title: 'Automatic Backup Location',
      selected: current,
      choices: [
        PolishedChoice(
          value: AutomaticBackupLocation.local,
          label: 'On My Device',
          subtitle: 'Store automatic backups in Trackmark on this device',
          leading: Icon(AppIcon.backup),
        ),
        PolishedChoice(
          value: AutomaticBackupLocation.iCloud,
          label: 'iCloud Drive',
          subtitle: 'Store automatic backups in your personal iCloud Drive',
          leading: Icon(AppIcon.cloud),
        ),
      ],
    );
    if (!mounted || selected == null || selected == current) return;

    if (selected == AutomaticBackupLocation.iCloud) {
      BackupStorageStatus availability;
      try {
        availability = await _iCloudBackupStorage.status();
      } on Object {
        availability = const BackupStorageStatus(
          state: BackupStorageState.unavailable,
        );
      }
      if (!mounted) return;
      if (availability.state != BackupStorageState.available &&
          availability.state != BackupStorageState.uploaded &&
          availability.state != BackupStorageState.waitingForUpload) {
        await showDialog<void>(
          context: context,
          builder: (dialogContext) => AlertDialog(
            title: const Text('iCloud Drive is unavailable'),
            content: const Text(
              "Trackmark couldn't access iCloud Drive. Check that you're signed into iCloud and that iCloud Drive is enabled.",
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('Close'),
              ),
            ],
          ),
        );
        return;
      }
    }

    AppHaptics.toggleSelection();
    await store.savePreferences(
      store.preferences.copyWith(automaticBackupLocation: selected),
    );
  }

  Future<void> _pickPreferredDailySyncTime(FinanceDataStore store) async {
    final preferences = store.preferences;
    final selected = await showTimePicker(
      context: context,
      initialTime: TimeOfDay(
        hour: preferences.preferredDailySyncMinutes ~/ 60,
        minute: preferences.preferredDailySyncMinutes % 60,
      ),
    );
    if (selected == null || !mounted) return;
    await store.savePreferences(
      store.preferences.copyWith(
        preferredDailySyncMinutes: selected.hour * 60 + selected.minute,
      ),
    );
  }

  Future<void> _pickPreferredAutomaticBackupTime(FinanceDataStore store) async {
    final preferences = store.preferences;
    final selected = await showTimePicker(
      context: context,
      initialTime: TimeOfDay(
        hour: preferences.preferredAutomaticBackupMinutes ~/ 60,
        minute: preferences.preferredAutomaticBackupMinutes % 60,
      ),
    );
    if (selected == null || !mounted) return;
    await store.savePreferences(
      store.preferences.copyWith(
        preferredAutomaticBackupMinutes: selected.hour * 60 + selected.minute,
      ),
    );
  }

  Future<void> _resetTrackmarkData() async {
    if (_isResettingData || _isImportingBackup) return;
    final store = FinanceDataStoreScope.read(context);

    final signedInForSync = widget.onSyncNow != null;
    if (signedInForSync &&
        (!store.hasRemoteSync || widget.syncLabel != 'Synced')) {
      await _showBackupError(
        context,
        'Resolve cloud sync and complete a successful sync before resetting. '
        'This prevents another device from restoring older data.',
        title: 'Cloud Sync Must Be Healthy',
      );
      return;
    }

    final resetChoice = await _showResetTrackmarkDataConfirmation(context);
    if (!mounted || resetChoice == null) return;

    setState(() => _isResettingData = true);
    final createdAt = widget.now?.call() ?? DateTime.now();
    ExportedFile? safetyBackup;
    try {
      final safetyJson = const BackupCodec().encodeJson(
        store.dataSet,
        exportedAt: createdAt,
      );
      try {
        safetyBackup = await _backupSafetyFileService.savePreResetBackup(
          content: safetyJson,
          createdAt: createdAt,
        );
      } on Object {
        if (!mounted) return;
        await _showBackupError(
          context,
          'Trackmark could not create and verify the required pre-reset '
          'safety backup. Nothing was changed.',
          title: 'Reset Stopped Safely',
        );
        return;
      }

      try {
        await store.resetTrackmarkData(
          resetAppSettings: resetChoice.resetAppSettings,
        );
      } on AuthoritativeRestoreLocalInstallException {
        if (!mounted) return;
        await _showBackupError(
          context,
          'The empty data set is now authoritative in Trackmark cloud sync, '
          'but this device could not finish saving its local copy. Your '
          'pre-reset safety backup is ${safetyBackup.fileName}. Close and '
          'reopen Trackmark, then sync again.',
          title: 'Reset Needs Attention',
        );
        return;
      } on Object {
        if (!mounted) return;
        await _showBackupError(
          context,
          'Trackmark could not complete the reset safely. Your existing data '
          'was retained. The safety backup remains at '
          '${safetyBackup.fileName}.',
          title: 'Reset Stopped Safely',
        );
        return;
      }

      if (resetChoice.resetAppSettings) {
        try {
          await const OnboardingPreferences().reset();
        } on Object {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text(
                  'Data was reset, but welcome preferences could not be reset. Use Reset Preferences to try again.',
                ),
              ),
            );
          }
        }
      }
      if (!mounted) return;
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Trackmark Data Reset'),
          content: Text(
            [
              if (store.hasRemoteSync)
                'The empty financial data set is now authoritative for your '
                    'Trackmark devices.'
              else
                'This device now has an empty financial data set.',
              if (resetChoice.resetAppSettings)
                'Your app settings were returned to their defaults. Your '
                    'sign-in and existing backup files were preserved.'
              else
                'Your app preferences and sign-in were preserved.',
              'A verified pre-reset safety backup was saved as '
                  '${safetyBackup!.fileName}.',
            ].join('\n\n'),
          ),
          actions: [
            TextButton(
              onPressed: () =>
                  _shareResetSafetyBackup(dialogContext, safetyBackup!),
              child: const Text('Share Safety Backup'),
            ),
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: const Text('Done'),
            ),
          ],
        ),
      );
    } finally {
      if (mounted) setState(() => _isResettingData = false);
    }
  }

  Future<void> _shareResetSafetyBackup(
    BuildContext anchorContext,
    ExportedFile safetyBackup,
  ) async {
    try {
      await _exportFileService.shareExistingFile(
        file: safetyBackup,
        shareTitle: 'Trackmark pre-reset safety backup',
        sharePositionOrigin: exportSharePositionOrigin(anchorContext),
      );
    } on Object {
      if (!anchorContext.mounted) return;
      ScaffoldMessenger.of(anchorContext).showSnackBar(
        const SnackBar(content: Text('Could not share the safety backup file')),
      );
    }
  }

  Future<void> _importBackup() async {
    if (_isImportingBackup) return;
    final store = FinanceDataStoreScope.read(context);
    setState(() => _isImportingBackup = true);
    try {
      final selected = await _backupImportFileService.selectBackup();
      if (!mounted || selected == null) return;

      final ValidatedBackup backup;
      try {
        backup = widget.backupRestoreValidator.validate(selected.content);
      } on BackupValidationException catch (error) {
        if (!mounted) return;
        await _showBackupError(context, error.message);
        return;
      } on Object {
        if (!mounted) return;
        await _showBackupError(
          context,
          'This backup could not be decoded safely. Your current data was not changed.',
        );
        return;
      }

      if (!mounted) return;
      final confirmed = await _showRestorePreview(
        context,
        backup: backup,
        fileName: selected.name,
        cloudEnabled: store.hasRemoteSync,
      );
      if (!mounted || confirmed != true) return;

      final createdAt = widget.now?.call() ?? DateTime.now();
      final safetyJson = const BackupCodec().encodeJson(
        store.dataSet,
        exportedAt: createdAt,
      );
      final ExportedFile safetyBackup;
      try {
        safetyBackup = await _backupSafetyFileService.savePreRestoreBackup(
          content: safetyJson,
          createdAt: createdAt,
        );
      } on Object {
        if (!mounted) return;
        await _showBackupError(
          context,
          'Trackmark could not create and verify the required pre-restore safety backup. Nothing was changed.',
        );
        return;
      }

      try {
        await store.restoreBackupDataSet(backup.dataSet);
      } on AuthoritativeRestoreLocalInstallException {
        if (!mounted) return;
        await _showBackupError(
          context,
          'The restored backup is now authoritative in Trackmark cloud sync, but this device could not finish saving its local copy. Your pre-restore safety backup is ${safetyBackup.fileName}. Close and reopen Trackmark, then sync again; stale cloud data cannot override the restored backup.',
          title: 'Backup Restore Needs Attention',
        );
        return;
      } on Object {
        if (!mounted) return;
        await _showBackupError(
          context,
          'Trackmark could not complete the restore safely. The prior local data was retained. The safety backup remains at ${safetyBackup.fileName}.',
        );
        return;
      }

      var notificationsRebuilt = true;
      try {
        await store.refreshScheduledNotifications();
      } on Object {
        // The authoritative replacement has already completed. A device-only
        // notification failure must not be reported as a rolled-back restore.
        notificationsRebuilt = false;
      }
      if (!mounted) return;
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Backup Restored'),
          content: Text(
            [
              if (store.hasRemoteSync)
                'Your Trackmark data was restored successfully and synchronized as the authoritative cloud dataset.'
              else
                'Your Trackmark data was restored successfully.',
              'A pre-restore safety backup was saved as ${safetyBackup.fileName}.',
              if (!notificationsRebuilt)
                'Trackmark could not re-register this device\'s scheduled notifications. Your restored data is safe; review notification settings to try again.',
            ].join('\n\n'),
          ),
          actions: [
            TextButton(
              onPressed: () => _shareSafetyBackup(dialogContext, safetyBackup),
              child: const Text('Share Safety Backup'),
            ),
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: const Text('Done'),
            ),
          ],
        ),
      );
    } on Object {
      if (!mounted) return;
      await _showBackupError(
        context,
        'Trackmark could not open the selected backup file. Your current data was not changed.',
      );
    } finally {
      if (mounted) setState(() => _isImportingBackup = false);
    }
  }

  Future<void> _shareSafetyBackup(
    BuildContext anchorContext,
    ExportedFile safetyBackup,
  ) async {
    try {
      await _exportFileService.shareExistingFile(
        file: safetyBackup,
        shareTitle: 'Trackmark pre-restore safety backup',
        sharePositionOrigin: exportSharePositionOrigin(anchorContext),
      );
    } on Object {
      if (!anchorContext.mounted) return;
      ScaffoldMessenger.of(anchorContext).showSnackBar(
        const SnackBar(content: Text('Could not share the safety backup file')),
      );
    }
  }

  Future<void> _showExportActions(
    BuildContext anchorContext, {
    required _ExportKind kind,
  }) async {
    if (_sharingExport != null) return;

    final sharePositionOrigin = exportSharePositionOrigin(anchorContext);
    final action = await _showExportActionSheet(context, kind: kind);
    if (!mounted || action == null) return;

    final store = FinanceDataStoreScope.read(context);
    final payload = switch (kind) {
      _ExportKind.csv => const BackupCodec().encodeTransactionsCsv(
        store.dataSet,
      ),
      _ExportKind.backup => const BackupCodec().encodeJson(store.dataSet),
    };

    if (action == _ExportAction.copy) {
      await copyExportToClipboard(
        context,
        title: kind == _ExportKind.csv
            ? 'CSV copied to clipboard'
            : 'Backup copied to clipboard',
        payload: payload,
      );
      return;
    }

    setState(() => _sharingExport = kind);
    final createdAt = widget.now?.call() ?? DateTime.now();
    try {
      await _exportFileService.shareTextFile(
        content: payload,
        fileName: kind == _ExportKind.csv
            ? csvExportFileName(createdAt)
            : backupExportFileName(createdAt),
        mimeType: kind == _ExportKind.csv ? 'text/csv' : 'application/json',
        shareTitle: kind == _ExportKind.csv
            ? 'Trackmark Money transactions'
            : 'Trackmark Money backup',
        sharePositionOrigin: sharePositionOrigin,
      );
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            kind == _ExportKind.csv
                ? 'Could not share CSV file'
                : 'Could not share backup file',
          ),
        ),
      );
    } finally {
      if (mounted) setState(() => _sharingExport = null);
    }
  }
}

Future<bool?> _showRestorePreview(
  BuildContext context, {
  required ValidatedBackup backup,
  required String fileName,
  required bool cloudEnabled,
}) {
  final dataSet = backup.dataSet;
  final exportedAt = backup.exportedAt?.toLocal();
  return showDialog<bool>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: const Text('Restore Backup?'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(fileName, style: Theme.of(context).textTheme.titleSmall),
            const SizedBox(height: 12),
            _BackupPreviewRow(
              label: 'Backup date',
              value: exportedAt == null
                  ? 'Not recorded'
                  : '${shortDate(exportedAt)} · ${TimeOfDay.fromDateTime(exportedAt).format(context)}',
            ),
            _BackupPreviewRow(
              label: 'Schema version',
              value: backup.sourceSchemaVersion == backup.schemaVersion
                  ? '${backup.schemaVersion}'
                  : '${backup.sourceSchemaVersion} → ${backup.schemaVersion}',
            ),
            _BackupPreviewRow(
              label: 'Accounts',
              value: '${dataSet.accounts.length}',
            ),
            _BackupPreviewRow(
              label: 'Transactions',
              value: '${dataSet.transactions.length}',
            ),
            _BackupPreviewRow(
              label: 'Scheduled Transactions',
              value: '${dataSet.scheduledTransactions.length}',
            ),
            _BackupPreviewRow(
              label: 'Categories',
              value: '${dataSet.categories.length}',
            ),
            _BackupPreviewRow(
              label: 'Budgets',
              value: '${dataSet.budgets.length}',
            ),
            _BackupPreviewRow(label: 'Goals', value: '${dataSet.goals.length}'),
            const SizedBox(height: 16),
            const Text(
              'Restoring this backup will replace the current Trackmark data on this device.',
            ),
            if (cloudEnabled) ...[
              const SizedBox(height: 10),
              const Text(
                'The restored backup will also become the authoritative Trackmark cloud dataset.',
              ),
              const SizedBox(height: 8),
              Text(
                'Update Trackmark on your other devices before their next sync. Older versions cannot read an authoritative restored dataset.',
                style: Theme.of(context).textTheme.bodySmall,
              ),
            ],
            const SizedBox(height: 10),
            Text(
              'Trackmark will create and verify a pre-restore safety backup before changing any data.',
              style: Theme.of(context).textTheme.bodySmall,
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(dialogContext).pop(false),
          child: const Text('Cancel'),
        ),
        FilledButton(
          style: FilledButton.styleFrom(backgroundColor: AppTheme.rose),
          onPressed: () => Navigator.of(dialogContext).pop(true),
          child: const Text('Restore Backup'),
        ),
      ],
    ),
  );
}

Future<void> _showBackupError(
  BuildContext context,
  String message, {
  String title = 'Backup Could Not Be Restored',
}) {
  return showDialog<void>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: Text(title),
      content: Text(message),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(dialogContext).pop(),
          child: const Text('Close'),
        ),
      ],
    ),
  );
}

class _BackupPreviewRow extends StatelessWidget {
  const _BackupPreviewRow({required this.label, required this.value});

  final String label;
  final String value;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: Row(
        children: [
          Expanded(child: Text(label)),
          const SizedBox(width: 16),
          Text(value, style: const TextStyle(fontWeight: FontWeight.w700)),
        ],
      ),
    );
  }
}

enum _ExportKind { csv, backup }

enum _ExportAction { share, copy }

Future<_ExportAction?> _showExportActionSheet(
  BuildContext context, {
  required _ExportKind kind,
}) {
  final isCsv = kind == _ExportKind.csv;
  return showModalBottomSheet<_ExportAction>(
    context: context,
    showDragHandle: true,
    useSafeArea: true,
    builder: (sheetContext) => Padding(
      padding: const EdgeInsets.fromLTRB(
        AppSpacing.lg,
        0,
        AppSpacing.lg,
        AppSpacing.lg,
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
