class CategorySpendingReport extends StatelessWidget {
  const CategorySpendingReport({
    required this.totals,
    required this.totalExpensesMinor,
    required this.currency,
    required this.colors,
    required this.expanded,
    required this.onSelected,
    super.key,
  });

  final List<CategoryReportTotal> totals;
  final int totalExpensesMinor;
  final CurrencyFormatSettings currency;
  final List<Color> colors;
  final bool expanded;
  final ValueChanged<CategoryReportTotal> onSelected;

  @override
  Widget build(BuildContext context) {
    final chart = Semantics(
      label:
          'Spending by category donut chart. Total expenses ${money(totalExpensesMinor, currency)}.',
      child: SizedBox(
        key: const ValueKey('spending-category-donut'),
        width: 190,
        height: 190,
        child: Stack(
          alignment: Alignment.center,
          children: [
            PieChart(
              PieChartData(
                centerSpaceRadius: 57,
                sectionsSpace: 2,
                pieTouchData: PieTouchData(
                  touchCallback: (event, response) {
                    if (event is! FlTapUpEvent ||
                        response?.touchedSection == null) {
                      return;
                    }
                    final index = response!.touchedSection!.touchedSectionIndex;
                    if (index >= 0 && index < totals.length) {
                      onSelected(totals[index]);
                    }
                  },
                ),
                sections: [
                  for (var index = 0; index < totals.length; index += 1)
                    PieChartSectionData(
                      value: totals[index].amountMinor.toDouble(),
                      color: colors[index % colors.length],
                      radius: 31,
                      showTitle: false,
                      borderSide: BorderSide.none,
                    ),
                ],
              ),
            ),
            Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  'Expenses',
                  style: Theme.of(context).textTheme.labelMedium?.copyWith(
                    color: Theme.of(context).colorScheme.onSurfaceVariant,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 2),
                FittedBox(
                  child: Text(
                    money(totalExpensesMinor, currency),
                    style: AppTextStyles.money(context, fontSize: 18),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
    final visibleTotals = expanded
        ? totals
        : totals.take(4).toList(growable: false);
    final ranking = Column(
      children: [
        for (var index = 0; index < visibleTotals.length; index += 1)
          CategoryReportRow(
            key: ValueKey('report-category-${visibleTotals[index].id}'),
            total: visibleTotals[index],
            color: colors[index % colors.length],
            currency: currency,
            selected: false,
            onTap: () => onSelected(visibleTotals[index]),
            showDivider: index != visibleTotals.length - 1,
          ),
      ],
    );

    if (!expanded) return ranking;

    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxWidth >= 620) {
          return Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Expanded(child: Center(child: chart)),
              const SizedBox(width: AppSpacing.lg),
              Expanded(child: ranking),
            ],
          );
        }
        return Column(
          children: [
            chart,
            const SizedBox(height: AppSpacing.sm),
            ranking,
          ],
        );
      },
    );
  }
}

