class SettingsActionRow extends StatelessWidget {
  const SettingsActionRow({
    required this.icon,
    required this.title,
    this.subtitle,
    this.subtitleMaxLines = 2,
    this.trailingText,
    this.showProgress = false,
    this.showStatusPill = false,
    this.showDivider = true,
    this.destructive = false,
    this.onTap,
    super.key,
  });

  final IconData icon;
  final String title;
  final String? subtitle;
  final int subtitleMaxLines;
  final String? trailingText;
  final bool showProgress;
  final bool showStatusPill;
  final bool showDivider;
  final bool destructive;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final foreground = destructive ? theme.colorScheme.error : null;
    return DecoratedBox(
      decoration: BoxDecoration(
        border: showDivider
            ? Border(
                bottom: BorderSide(
                  color: theme.colorScheme.outlineVariant.withValues(
                    alpha: 0.45,
                  ),
                ),
              )
            : null,
      ),
      child: ListTile(
        minTileHeight: 66,
        contentPadding: const EdgeInsets.symmetric(horizontal: AppSpacing.md),
        leading: SettingsRowIcon(
          icon: icon,
          color: destructive ? theme.colorScheme.error : AppTheme.accent,
        ),
        title: Text(
          title,
          style: TextStyle(fontWeight: FontWeight.w800, color: foreground),
        ),
        subtitle: subtitle == null
            ? null
            : Text(
                subtitle!,
                maxLines: subtitleMaxLines,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  color: theme.colorScheme.onSurfaceVariant,
                  height: 1.2,
                ),
              ),
        trailing: showProgress
            ? const SizedBox.square(
                dimension: 20,
                child: CircularProgressIndicator.adaptive(strokeWidth: 2),
              )
            : showStatusPill && trailingText != null
            ? Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 10,
                  vertical: 5,
                ),
                decoration: BoxDecoration(
                  color: AppTheme.accent.withValues(alpha: 0.11),
                  borderRadius: BorderRadius.circular(AppRadii.pill),
                ),
                child: Text(
                  trailingText!,
                  style: const TextStyle(
                    color: AppTheme.accent,
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              )
            : onTap != null
            ? Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (trailingText != null) ...[
                    Text(
                      trailingText!,
                      style: TextStyle(
                        color: destructive
                            ? theme.colorScheme.error
                            : theme.colorScheme.onSurfaceVariant,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                    SizedBox(width: 4),
                  ],
                  Icon(
                    AppIcon.chevronRightRounded,
                    color: destructive
                        ? theme.colorScheme.error
                        : theme.colorScheme.onSurfaceVariant,
                  ),
                ],
              )
            : trailingText == null
            ? null
            : Text(
                trailingText!,
                style: TextStyle(color: theme.colorScheme.onSurfaceVariant),
              ),
        onTap: onTap,
      ),
    );
  }
}

