Future<void> copyExportToClipboard(
  BuildContext context, {
  required String title,
  required String payload,
}) async {
  await Clipboard.setData(ClipboardData(text: payload));
  if (!context.mounted) return;
  ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(title)));
}

class AccountBalancePanel extends StatelessWidget {
  const AccountBalancePanel({
    this.title = 'Accounts',
    this.maxRows,
    this.compact = false,
    super.key,
  });

  final String title;
  final int? maxRows;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final store = FinanceDataStoreScope.watch(context);
    final currency = store.preferences.currency;
    final accounts = store.activeAccountsInDisplayOrder.take(
      maxRows ?? store.accounts.length,
    );
    return AppCard(
      title: title,
      padding: EdgeInsets.all(compact ? AppSpacing.sm : AppSpacing.md),
      child: Column(
        children: [
          if (accounts.isEmpty)
            CompactEmptyRow(icon: AppIcon.wallet, label: 'No accounts yet'),
          for (final account in accounts)
            MetricRow(
              label: account.name,
              value: money(
                store.clearedBalanceForAccount(account.id),
                currency,
              ),
              icon: accountGroupIcon(account.group.name),
              compact: compact,
            ),
        ],
      ),
    );
  }
}

