        return FractionallySizedBox(
          heightFactor: 0.92,
          child: _AccountDetailsView(
            account: account,
            store: dataStore,
            onEdit: () async {
              await showEditAccountDialog(sheetContext, account);
              if (sheetContext.mounted) setSheetState(() {});
            },
          ),
        );
      },
    ),
  );
}

class _AccountDetailsView extends StatelessWidget {
  const _AccountDetailsView({
    required this.account,
    required this.store,
    required this.onEdit,
  });

  final v2_account.AccountRecord account;
  final FinanceDataStore store;
  final VoidCallback onEdit;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final balanceMinor = store.clearedBalanceForAccount(account.id);
    final pendingEffectMinor = store.pendingEffectForAccount(account.id);
    final reservedMinor = store.reservedForAccount(account.id);
    final availableToSpendMinor = store.availableToSpendForAccount(account.id);
    final reservationBreakdown = store.reservationBreakdownForAccount(
      account.id,
    );
    final activity = _latestActivity;
    final icon = AccountAppearanceCatalog.iconFor(
      account.type,
      account.appearanceIconId,
    );
    final accent = AccountAppearanceCatalog.accentFor(
      account.appearanceAccentId,
    );

    return Column(
      key: const ValueKey('account-details-view'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(
            AppSpacing.lg,
            0,
            AppSpacing.sm,
            AppSpacing.sm,
          ),
          child: Row(
            children: [
              Expanded(
                child: Text(
                  'Account Details',
                  style: theme.textTheme.headlineSmall?.copyWith(
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              TextButton(
                key: const ValueKey('account-details-edit'),
                onPressed: onEdit,
                child: const Text('Edit'),
              ),
            ],
          ),
        ),
        Expanded(
          child: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(
              AppSpacing.lg,
              0,
              AppSpacing.lg,
              AppSpacing.xl,
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                _AccountDetailsHeader(
                  account: account,
                  balanceMinor: balanceMinor,
                  currency: store.preferences.currency,
                ),
                const SizedBox(height: AppSpacing.md),
                if (_showsSpendableAvailability(account)) ...[
                  _AccountDetailsSection(
                    title: 'Available Money',
                    children: [
                      _AccountDetailsRow(
                        label: 'Balance',
                        value: money(balanceMinor, store.preferences.currency),
                      ),
                      _AccountDetailsRow(
                        label: 'Pending',
                        value: money(
                          pendingEffectMinor,
                          store.preferences.currency,
                        ),
                      ),
                      _AccountDetailsRow(
                        label: 'Reserved',
                        value: money(reservedMinor, store.preferences.currency),
                      ),
                      for (final reservation in reservationBreakdown)
                        _AccountDetailsRow(
                          label:
                              '  ${reservation.name} ${reservation.type == ReservationContainerType.fund ? 'Fund' : 'Goal'}',
                          value: money(
                            reservation.amountMinor,
                            store.preferences.currency,
                          ),
                        ),
                      _AccountDetailsRow(
                        label: 'Available to Spend',
                        value: money(
                          availableToSpendMinor,
                          store.preferences.currency,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: AppSpacing.md),
                ],
                _AccountDetailsSection(
                  title: 'Account Information',
                  children: [
                    _AccountDetailsRow(
                      label: 'Account Type',
                      value: v2AccountTypeLabel(account.type),
                    ),
                    _AccountDetailsRow(
                      label: 'Last Activity',
                      value: activity == null
                          ? 'No transactions yet'
                          : _activityName(activity),
                    ),
                    if (activity != null)
                      _AccountDetailsRow(
                        label: 'Activity Date',
                        value: fullMonthDateLabel(activity.date),
                      ),
                    if (account.type == v2_account.AccountType.loan)
                      _AccountDetailsRow(
                        label: 'Original Loan Amount',
                        value: account.originalLoanAmountMinor == null
                            ? '–'
                            : money(
                                account.originalLoanAmountMinor!,
                                store.preferences.currency,
                              ),
                      ),
                  ],
                ),
                if (account.type == v2_account.AccountType.creditCard) ...[
                  const SizedBox(height: AppSpacing.md),
                  _CreditCardAccountDetails(
                    account: account,
                    store: store,
                    balanceMinor: balanceMinor,
                  ),
                ],
                const SizedBox(height: AppSpacing.md),
                _AccountDetailsSection(
                  title: 'Balance Options',
                  children: [
                    _AccountDetailsRow(
                      label: 'Included in Group Totals',
                      value: account.includeInGroupBalance ? 'Yes' : 'No',
                    ),
                    _AccountDetailsRow(
                      label: 'Included in net worth',
                      value: account.includeInNetWorth ? 'Yes' : 'No',
                    ),
                  ],
                ),
                const SizedBox(height: AppSpacing.md),
                _AccountDetailsSection(
                  title: 'Appearance',
                  leading: AccountAppearanceBadge(
                    accountType: account.type,
                    iconId: account.appearanceIconId,
                    accentId: account.appearanceAccentId,
                    size: 38,
                  ),
                  children: [
                    _AccountDetailsRow(label: 'Icon', value: icon.label),
                    _AccountDetailsRow(
                      label: 'Accent Color',
                      value: accent?.label ?? 'Default',
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  TransactionRecord? get _latestActivity {
    final activity =
        store.transactions
            .where(
              (transaction) =>
                  !transaction.isDeleted &&
                  (transaction.accountId == account.id ||
                      transaction.transferAccountId == account.id),
            )
            .toList(growable: false)
          ..sort((a, b) => b.date.compareTo(a.date));
    return activity.isEmpty ? null : activity.first;
  }

  String _activityName(TransactionRecord transaction) {
    final payee = transaction.payee.trim();
    return payee.isEmpty ? transactionTypeLabel(transaction.type) : payee;
  }
}

